def scrape_first_tag_text(url, tag, timeout=10, headers=None):
    """
    Fetch `url`, find the first occurrence of HTML tag `tag`, and return its text content.
    Tries to use (in order) b34.BeautifulSoup, bs4.BeautifulSoup, and a pure-stdlib parser fallback.
    Uses requests if available, otherwise urllib.

    Args:
        url (str): URL to fetch.
        tag (str): Tag name to search for (e.g. 'h1', 'p', 'div').
        timeout (float): Network timeout in seconds.
        headers (dict or None): Optional request headers.

    Returns:
        str or None: Text content of the first matching tag (stripped), or None if not found.

    Raises:
        ValueError: If tag is empty or not a string.
        RuntimeError: On network or decoding errors.
    """
    if not isinstance(tag, str) or not tag.strip():
        raise ValueError("tag must be a non-empty string")
    tag = tag.strip()

    # Try imports
    try:
        from b34 import BeautifulSoup as _BeautifulSoup  # try b34 if it exists
    except Exception:
        try:
            from bs4 import BeautifulSoup as _BeautifulSoup  # try bs4
        except Exception:
            _BeautifulSoup = None

    try:
        import requests as _requests
    except Exception:
        _requests = None

    # Prepare headers
    headers = headers or {"User-Agent": "python-scraper/1.0"}

    # Fetch HTML
    html = None
    if _requests:
        try:
            resp = _requests.get(url, headers=headers, timeout=timeout)
            resp.raise_for_status()
            # requests will decode according to headers/charset
            html = resp.text
        except Exception as e:
            raise RuntimeError(f"Error fetching {url}: {e}")
    else:
        # urllib fallback
        try:
            from urllib.request import Request, urlopen
            req = Request(url, headers=headers)
            with urlopen(req, timeout=timeout) as resp:
                raw = resp.read()
                # Try to get charset from headers, fallback to utf-8
                charset = None
                try:
                    content_type = resp.headers.get_content_charset()
                    if content_type:
                        charset = content_type
                except Exception:
                    charset = None
                if not charset:
                    charset = "utf-8"
                html = raw.decode(charset, errors="replace")
        except Exception as e:
            raise RuntimeError(f"Error fetching {url}: {e}")

    # Parse and find first tag
    if _BeautifulSoup is not None:
        soup = _BeautifulSoup(html, "html.parser")
        el = soup.find(tag)
        if el is None:
            return None
        return el.get_text(strip=True) or None

    # Pure-stdlib fallback using html.parser
    from html.parser import HTMLParser
    import html as _html_module

    class FirstTagParser(HTMLParser):
        def __init__(self, target):
            super().__init__(convert_charrefs=False)
            self.target = target.lower()
            self.recording = False
            self.depth = 0
            self.parts = []

        def handle_starttag(self, name, attrs):
            lname = name.lower()
            if not self.recording and lname == self.target:
                self.recording = True
                self.depth = 1
            elif self.recording:
                self.depth += 1

        def handle_endtag(self, name):
            if self.recording:
                lname = name.lower()
                if lname == self.target:
                    self.depth -= 1
                    if self.depth <= 0:
                        # stop further parsing by raising a controlled exception
                        raise StopIteration
                else:
                    self.depth -= 1

        def handle_data(self, data):
            if self.recording:
                self.parts.append(data)

        def handle_entityref(self, name):
            if self.recording:
                self.parts.append(_html_module.unescape(f"&{name};"))

        def handle_charref(self, name):
            if self.recording:
                # name may be 'xHH' or decimal; unescape handles both
                self.parts.append(_html_module.unescape(f"&#{name};"))

    parser = FirstTagParser(tag)
    try:
        parser.feed(html)
    except StopIteration:
        # normal early stop when closing the target tag
        pass
    text = "".join(parser.parts).strip()
    return text or None
