    - title: optional title string
    - xlabel, ylabel: axis labels
    - random_seed: optional int to make color selection reproducible
    - rotation: x-tick label rotation (useful for long usernames)

    Returns:
    - Matplotlib Axes object for the plot.
    """
    if not colors:
        raise ValueError("colors list must contain at least one color")

    if random_seed is not None:
        random.seed(random_seed)
    color = random.choice(colors)

    # Extract from_user values robustly
    from_users = []

    # If it's a pandas DataFrame, handle that case without requiring pandas in signature
    try:
        import pandas as pd
    except Exception:
        pd = None

    if pd is not None and isinstance(result, pd.DataFrame):
        if 'from_user' not in result.columns:
            raise KeyError("DataFrame does not contain a 'from_user' column")
        from_users = result['from_user'].dropna().astype(str).tolist()
    else:
        # handle single dict or object
        if isinstance(result, dict):
            if 'from_user' in result:
                from_users = [result['from_user']]
            else:
                raise KeyError("dict does not contain a 'from_user' key")
        else:
            # try to iterate
            try:
                iterator = iter(result)
            except TypeError:
                # single object with attribute
                if hasattr(result, 'from_user'):
                    from_users = [getattr(result, 'from_user')]
                else:
                    raise TypeError("Unsupported result type; cannot obtain from_user values")
            else:
                for item in iterator:
                    if item is None:
                        continue
                    if isinstance(item, dict):
                        if 'from_user' in item:
                            from_users.append(item['from_user'])
                        else:
                            # skip items without the key
                            continue
                    elif hasattr(item, 'from_user'):
                        from_users.append(getattr(item, 'from_user'))
                    elif isinstance(item, str):
                        from_users.append(item)
                    else:
                        # fallback: try to get 'from_user' via get attribute or key, else skip
                        try:
                            val = item.get('from_user')  # in case it's a mapping-like object
                            if val is not None:
                                from_users.append(val)
                        except Exception:
                            continue

    # Normalize to strings and filter empties
    from_users = [str(x) for x in from_users if x is not None and str(x) != ""]

    if not from_users:
        raise ValueError("No from_user values found in result")

    # Use seaborn histplot with discrete=True to produce counts for categorical values
    plt.figure(figsize=figsize)
    ax = sns.histplot(x=from_users, discrete=True, color=color)
    ax.set_xlabel(xlabel)
    ax.set_ylabel(ylabel)
    if title:
        ax.set_title(title)
    plt.xticks(rotation=rotation, ha='right')
    plt.tight_layout()
    plt.show()

    return ax
