```python
import random

def veg_stats(preferences, seed=None, use_pandas=False):
    """
    Calculate statistics for vegetables preferred by people.

    Args:
      preferences (dict): mapping person -> vegetable or list/tuple of vegetables.
                          Example: {"Alice": ["carrot","pea"], "Bob": "carrot"}
      seed (int, optional): random seed for reproducibility.
      use_pandas (bool, optional): if True and pandas is installed, a pandas.DataFrame
                                   will be included in the returned dict under 'df'.

    Returns:
      dict with keys:
        - 'veg_to_people': {vegetable: [people,...]}
        - 'veg_counts': {vegetable: count}
        - 'veg_percentages': {vegetable: percentage_of_total_counts (float)}
        - 'veg_to_person': {vegetable: chosen_person}
        - 'df' (optional): pandas.DataFrame with columns
            ['vegetable','count','percentage','people','representative'] if pandas used.
    """
    if seed is not None:
        random.seed(seed)

    # Normalize preferences: ensure each value is an iterable of vegetables
    veg_to_people = {}
    for person, vegs in preferences.items():
        if vegs is None:
            continue
        # accept single string or iterable of strings
        if isinstance(vegs, str):
            iterable = [vegs]
        else:
            try:
                # treat as iterable (list/tuple/set)
                iterable = list(vegs)
            except TypeError:
                iterable = [vegs]
        for veg in iterable:
            if veg is None:
                continue
            veg_to_people.setdefault(veg, []).append(person)

    # Assign random counts to each vegetable (1..10)
    veg_counts = {veg: random.randint(1, 10) for veg in veg_to_people}

    # Compute total and percentages
    total = sum(veg_counts.values())
    if total == 0:
        veg_percentages = {veg: 0.0 for veg in veg_counts}
    else:
        veg_percentages = {veg: round((count / total) * 100, 2) for veg, count in veg_counts.items()}

    # Map each vegetable to a (single) person from those who listed it.
    # Choose randomly among people who listed the vegetable.
    veg_to_person = {}
    for veg, people in veg_to_people.items():
        if people:
            veg_to_person[veg] = random.choice(people)
        else:
            veg_to_person[veg] = None

    result = {
        "veg_to_people": veg_to_people,
        "veg_counts": veg_counts,
        "veg_percentages": veg_percentages,
        "veg_to_person": veg_to_person,
    }

    # Optionally create a pandas DataFrame if requested and available
    if use_pandas:
        try:
            import pandas as pd
            rows = []
            for veg in veg_to_people:
                rows.append({
                    "vegetable": veg,
                    "count": veg_counts.get(veg, 0),
                    "percentage": veg_percentages.get(veg, 0.0),
                    "people": veg_to_people.get(veg, []),
                    "representative": veg_to_person.get(veg),
                })
            df = pd.DataFrame(rows)
            # sort by count descending for convenience
            df = df.sort_values(by="count", ascending=False).reset_index(drop=True)
            result["df"] = df
        except Exception:
            # pandas not available; ignore and return pure-Python structures
            pass

    return result
