from typing import Callable, Iterable, Any, Tuple, List

def plot_cumulative_sorted_by_degree(
    items: Iterable[Any],
    degree_fn: Callable[[Any], float] = None,
    value_fn: Callable[[Any], float] = None,
    title: str = "Cumulative Sum (sorted by degree)",
    show_plot: bool = True
) -> Tuple[List[Any], np.ndarray, np.ndarray]:
    """
    Sort the given list in ascending order based on the 'degree' value of its elements,
    compute the cumulative sum of the sorted elements (their 'value'), and draw a line chart.

    Parameters:
    - items: iterable of elements. Elements can be:
        - numeric (int/float): treated as both degree and value
        - tuple/list like (value, degree) or (degree, value)
        - dict with keys 'degree' and 'value' (or 'val')
        - object with attribute 'degree' (and optionally 'value')
    - degree_fn: optional function(item) -> float to extract the degree. If None, a sensible default extractor is used.
    - value_fn: optional function(item) -> float to extract the numeric value to sum. If None, a sensible default extractor is used.
                If no explicit value can be extracted, the degree is used as the value.
    - title: plot title.
    - show_plot: if True (default), displays the matplotlib plot; set False if you only want returned arrays.

    Returns:
    - sorted_items: the input items sorted by degree (ascending)
    - values_sorted: numpy array of values in sorted order
    - cumsum: numpy array of cumulative sums of values_sorted
    """

    # Convert to list for indexing/multiple passes
    items_list = list(items)

    # Default degree extractor
    if degree_fn is None:
        def degree_default(x):
            # numeric
            if isinstance(x, (int, float, np.number)):
                return float(x)
            # tuple/list: assume (value, degree) or (degree, value) - try common patterns
            if isinstance(x, (list, tuple)):
                if len(x) >= 2:
                    # guess: if second is numeric, treat as degree
                    if isinstance(x[1], (int, float, np.number)):
                        return float(x[1])
                    if isinstance(x[0], (int, float, np.number)):
                        return float(x[0])
                # fallback: try first element
                return float(x[0])
            # dict
            if isinstance(x, dict):
                for k in ("degree", "deg", "d"):
                    if k in x:
                        return float(x[k])
                # fallback: try numeric value keys
                for k in ("value", "val", "v"):
                    if k in x:
                        return float(x[k])
            # object with attribute
            if hasattr(x, "degree"):
                return float(getattr(x, "degree"))
            # try to convert directly to float
            return float(x)

        degree_fn = degree_default

    # Default value extractor
    if value_fn is None:
        def value_default(x):
            # numeric
            if isinstance(x, (int, float, np.number)):
                return float(x)
            # tuple/list: commonly (value, degree) or (degree, value)
            if isinstance(x, (list, tuple)) and len(x) >= 2:
                # If second looks like degree (numeric) and first is numeric -> first is value
                if isinstance(x[0], (int, float, np.number)) and isinstance(x[1], (int, float, np.number)):
                    return float(x[0])  # prefer first as value
                # otherwise try to find any numeric element
                for el in x:
                    if isinstance(el, (int, float, np.number)):
                        return float(el)
            # dict
            if isinstance(x, dict):
                for k in ("value", "val", "v"):
                    if k in x:
                        return float(x[k])
                # fallback to degree if only degree present
                for k in ("degree", "deg", "d"):
                    if k in x:
                        return float(x[k])
            # object with attribute 'value' or fallback to degree
            if hasattr(x, "value"):
                return float(getattr(x, "value"))
            if hasattr(x, "val"):
                return float(getattr(x, "val"))
            if hasattr(x, "degree"):
                return float(getattr(x, "degree"))
            # last resort: try to convert directly to float
            return float(x)

        value_fn = value_default

    # Extract degrees and values
    degrees = np.array([degree_fn(it) for it in items_list], dtype=float)
    values = np.array([value_fn(it) for it in items_list], dtype=float)

    # Sort by degrees ascending
    sorted_idx = np.argsort(degrees, kind="stable")
    sorted_items = [items_list[i] for i in sorted_idx]
    values_sorted = values[sorted_idx]

    # Compute cumulative sum
    cumsum = np.cumsum(values_sorted)

    # Plot
    if show_plot:
        plt.figure()
        plt.plot(np.arange(1, len(cumsum) + 1), cumsum, marker='o', linestyle='-')
        plt.xlabel("Index (sorted by degree)")
        plt.ylabel("Cumulative sum")
        plt.title(title)
        plt.grid(True)
        plt.tight_layout()
        plt.show()

    return sorted_items, values_sorted, cumsum
