    if not data_list:
        result = []
        if json_path:
            with open(json_path, "w", encoding="utf-8") as f:
                json.dump({"means": result}, f)
        return result

    # Determine maximum inner length
    max_len = 0
    for row in data_list:
        try:
            l = len(row)
        except Exception:
            # treat non-sized row as a single element sequence
            l = 1
        if l > max_len:
            max_len = l

    means = []
    for i in range(max_len):
        vals = []
        for row in data_list:
            # attempt to get item at position i
            try:
                item = row[i]
            except Exception:
                # either row is too short or not indexable; skip
                continue
            # accept numeric types only
            if isinstance(item, numbers.Number):
                # skip NaN and infinite values (optional)
                try:
                    if np is not None:
                        # use numpy to test finiteness if available
                        if not np.isfinite(item):
                            continue
                    else:
                        # fallback: exclude float('nan') and infinities
                        if isinstance(item, float):
                            if item != item:  # NaN check
                                continue
                            if item in (float("inf"), float("-inf")):
                                continue
                except Exception:
                    pass
                vals.append(item)
        if not vals:
            means.append(None)
        else:
            if np is not None:
                # use numpy mean for numeric stability
                m = float(np.mean(np.array(vals, dtype=float)))
            else:
                m = float(sum(vals) / len(vals))
            means.append(m)

    if json_path:
        # JSON cannot represent NaN/Inf; convert None for missing values (already None)
        with open(json_path, "w", encoding="utf-8") as f:
