import json
import math

def compute_position_means(data, json_path=None, use_numpy=True):
    """
    Compute mean of numeric values for each position across rows.

    Parameters:
    - data: iterable of iterables (e.g., list of lists/tuples). Each inner sequence
            contains numeric values (or values convertible to float). Rows may
            have different lengths.
    - json_path: optional path to write JSON array of means. Positions with no
                 numeric values are written as null.
    - use_numpy: if True, try to use numpy for faster computation; if numpy
                 isn't available it will fall back to a pure-Python method.

    Returns:
    - List of means (float) for each position. If a position has no numeric
      values, its entry is None.
    """
    # Normalize input to a list of lists
    rows = [list(r) for r in data] if data else []
    if not rows:
        # Nothing to do
        if json_path:
            with open(json_path, "w") as f:
                json.dump([], f)
        return []

    max_len = max((len(r) for r in rows), default=0)

    # Try numpy approach if requested
    if use_numpy:
        try:
            import numpy as np
            arr = np.full((len(rows), max_len), np.nan, dtype=float)
            for i, r in enumerate(rows):
                for j, v in enumerate(r):
                    try:
                        arr[i, j] = float(v)
                    except (TypeError, ValueError):
                        # leave as NaN (ignored in mean)
                        arr[i, j] = np.nan
            means = np.nanmean(arr, axis=0)
            result = [None if np.isnan(x) else float(x) for x in means]
        except Exception:
            # Fall back to pure-Python if numpy not available or fails
            result = []
            for j in range(max_len):
                vals = []
                for r in rows:
                    if j < len(r):
                        try:
                            vals.append(float(r[j]))
                        except (TypeError, ValueError):
                            pass
                if vals:
                    result.append(sum(vals) / len(vals))
                else:
                    result.append(None)
    else:
        # Pure-Python implementation
        result = []
        for j in range(max_len):
            vals = []
            for r in rows:
                if j < len(r):
                    try:
                        vals.append(float(r[j]))
                    except (TypeError, ValueError):
                        pass
            if vals:
                result.append(sum(vals) / len(vals))
            else:
                result.append(None)

    # Optionally write to JSON, converting None -> null in JSON
    if json_path:
        with open(json_path, "w") as f:
            json.dump(result, f, indent=2)

    return result
