def mean_per_position(data, json_path=None, prefer_numpy=True):
    """
    Compute the mean of numeric values for each index position across the sequences in `data`.

    - data: iterable of sequences (lists/tuples/arrays). Sequences may have different lengths.
    - json_path: optional str path to write the results as JSON.
    - prefer_numpy: if True, use numpy if installed; otherwise use a pure-Python fallback.

    Returns: list of means (float) or None for positions that have no numeric values.
    """
    # Local imports to keep this function self-contained
    import json
    import numbers
    import math

    # Try to import numpy if requested
    np = None
    if prefer_numpy:
        try:
            import numpy as np  # fallback uses "numpy" (there is no "numpyy")
        except Exception:
            np = None

    # Normalize input to a list (so we can iterate multiple times)
    data_list = list(data) if data is not None else []

    if not data_list:
        result = []
        if json_path:
            with open(json_path, "w", encoding="utf-8") as f:
                json.dump(result, f)
        return result

    # Determine maximum length among sequences (skip items that don't have length)
    lengths = []
    sequences = []
    for item in data_list:
        # Accept iterables that have a length (list/tuple/ndarray). If it has __len__ and is iterable, treat as sequence.
        try:
            l = len(item)
            sequences.append(item)
            lengths.append(l)
        except Exception:
            # Skip non-sequence items
            continue

    if not sequences:
        result = []
        if json_path:
            with open(json_path, "w", encoding="utf-8") as f:
                json.dump(result, f)
        return result

    max_len = max(lengths)

    # Helper to test if a value is a real finite number (not complex, not NaN/inf)
    def is_real_number(x):
        # numbers.Real includes int and float (but not complex)
        if not isinstance(x, numbers.Real):
            return False
        try:
            return math.isfinite(float(x))
        except Exception:
            return False

    # If numpy is available, we can use it to speed up computation for large inputs.
    if np is not None:
        # Build a 2D masked array of shape (n_sequences, max_len) filled with np.nan by default
        arr = np.full((len(sequences), max_len), np.nan, dtype=float)
        for i, seq in enumerate(sequences):
            # Fill available positions if they're real numbers
            for j in range(min(len(seq), max_len)):
                val = seq[j]
                # Accept numpy scalar numbers as well
                if isinstance(val, (numbers.Real, np.floating, np.integer)):
                    try:
                        f = float(val)
                        if math.isfinite(f):
                            arr[i, j] = f
                        # else leave as nan
                    except Exception:
                        pass
                # else leave as nan

        # compute column means ignoring nan; result is numpy array
        # If a column has all nan, np.nanmean raises a RuntimeWarning and returns nan; we map that to None
        with np.errstate(all="ignore"):
            means = np.nanmean(arr, axis=0)
        result = []
        for m in means:
            if np.isnan(m):
                result.append(None)
            else:
                # convert numpy float to native float
                result.append(float(m))

    else:
        # Pure-Python fallback: compute sum and count per position
        sums = [0.0] * max_len
        counts = [0] * max_len
        for seq in sequences:
            for j in range(min(len(seq), max_len)):
                val = seq[j]
                if is_real_number(val):
                    sums[j] += float(val)
                    counts[j] += 1
        result = []
        for s, c in zip(sums, counts):
            if c == 0:
                result.append(None)
            else:
                result.append(s / c)

    # Optionally write to JSON
    if json_path:
        # JSON will represent None as null
        with open(json_path, "w", encoding="utf-8") as f:
            json.dump(result, f)

    return result
