```python
def count_unique_nonstop_words(directory_path, recursive=False, encoding='utf-8', language='english'):
    """
    Count unique non-stop words across all '.txt' files in directory_path.

    Parameters:
    - directory_path (str): Path to the directory containing .txt files.
    - recursive (bool): If True, search subdirectories recursively. Default False.
    - encoding (str): File encoding to use when opening .txt files. Default 'utf-8'.
    - language (str): Language for stopwords (default 'english').

    Returns:
    - int: Number of unique non-stop words found across all .txt files.
    """
    import os
    import re

    try:
        import nltk
        from nltk.corpus import stopwords
    except ImportError as exc:
        raise ImportError("This function requires the 'nltk' package. Install it with 'pip install nltk'.") from exc

    # Ensure stopwords corpus is available
    try:
        stopset = set(w.lower() for w in stopwords.words(language))
    except LookupError:
        nltk.download('stopwords', quiet=True)
        stopset = set(w.lower() for w in stopwords.words(language))

    # Pattern to capture words (letters, optional internal apostrophe for contractions)
    word_pattern = re.compile(r"[A-Za-z]+(?:'[A-Za-z]+)?")

    unique_words = set()

    # Walk directory (optionally recursive)
    if recursive:
        walker = os.walk(directory_path)
    else:
        # non-recursive: only list files in the given directory
        def _single_level_walk(dirpath):
            try:
                names = os.listdir(dirpath)
            except FileNotFoundError:
                return
            files = []
            dirs = []
            for name in names:
                full = os.path.join(dirpath, name)
                if os.path.isdir(full):
                    dirs.append(name)
                else:
                    files.append(name)
            yield dirpath, dirs, files
        walker = _single_level_walk(directory_path)

    for root, _, files in walker:
        for fname in files:
            if fname.lower().endswith('.txt'):
                path = os.path.join(root, fname)
                try:
                    with open(path, 'r', encoding=encoding, errors='ignore') as fh:
                        text = fh.read().lower()
                except Exception:
                    # skip files that can't be read
                    continue

                for w in word_pattern.findall(text):
                    if w not in stopset:
                        unique_words.add(w)

    return len(unique_words)
