            if hasattr(os, 'getloadavg') and os.cpu_count() and os.cpu_count() > 0:
                load1, load5, load15 = os.getloadavg()
                cpu_percent = min(100.0, (load1 / os.cpu_count()) * 100.0)
            else:
                cpu_percent = 0.0
    except Exception:
        cpu_percent = 0.0

    # Gather memory usage
    mem_total = mem_used = mem_percent = None
    try:
        if psutil:
            vm = psutil.virtual_memory()
            mem_total = vm.total
            mem_used = vm.total - vm.available
            mem_percent = vm.percent
        else:
            # Try Linux /proc/meminfo
            if os.path.exists('/proc/meminfo'):
                meminfo = {}
                with open('/proc/meminfo', 'r') as f:
                    for line in f:
                        parts = line.split(':')
                        if len(parts) >= 2:
                            key = parts[0]
                            val = parts[1].strip().split()[0]
                            try:
                                meminfo[key] = int(val)  # kB
                            except Exception:
                                pass
                if 'MemTotal' in meminfo:
                    mem_total = meminfo['MemTotal'] * 1024
                    # Prefer MemAvailable, else compute used = total - MemFree - Buffers - Cached
                    if 'MemAvailable' in meminfo:
                        mem_available = meminfo['MemAvailable'] * 1024
                        mem_used = mem_total - mem_available
                    else:
                        mem_free = meminfo.get('MemFree', 0) * 1024
                        buffers = meminfo.get('Buffers', 0) * 1024
                        cached = meminfo.get('Cached', 0) * 1024
                        mem_used = mem_total - (mem_free + buffers + cached)
                    mem_percent = (mem_used / mem_total) * 100 if mem_total else 0.0
                else:
                    mem_total = mem_used = mem_percent = 0
            else:
                # Last resort: set zeros
                mem_total = mem_used = mem_percent = 0
    except Exception:
        mem_total = mem_used = mem_percent = 0

    # Gather disk usage for root '/'
    try:
        du = shutil.disk_usage(os.path.expanduser(os.sep))
        disk_total = du.total
        disk_free = du.free
        disk_used = du.used
