    except Exception:
        disk_total = disk_used = disk_percent = 0

    # Format values
    cpu_str = f"{cpu_percent:.1f} %"
    mem_str = f"{mem_percent:.1f} % ({_bytes2human(mem_used)} / {_bytes2human(mem_total)})" if mem_total else "N/A"
    disk_str = f"{disk_percent:.1f} % ({_bytes2human(disk_used)} / {_bytes2human(disk_total)})" if disk_total else "N/A"

    headers = ["Metric", "Usage"]
