def generate_system_usage_table(path='/', interval=0.1):
    """
    Return an ASCII table showing CPU usage, memory usage, and disk usage.

    Notes:
    - Tries to use psutil if available for the most accurate results; otherwise
      falls back to cross-platform methods (Linux / Windows / generic).
    - The function does not require any third-party 'txttable' library; it
      includes a minimal built-in ASCII table renderer so it's fully self-contained.
    - Returns the table as a string.

    Example:
        print(generate_system_usage_table())
    """
    import os
    import shutil
    import platform
    import subprocess
    import time

    # Try to import psutil if available
    try:
        import psutil
    except Exception:
        psutil = None

    # Helper: human-readable byte formatting
    def format_bytes(num):
        for unit in ['B', 'KB', 'MB', 'GB', 'TB', 'PB']:
            if abs(num) < 1024.0 or unit == 'PB':
                return f"{num:3.1f} {unit}"
            num /= 1024.0
        return f"{num:.1f} PB"

    # CPU usage
    def get_cpu_percent(interval):
        if psutil:
            try:
                # psutil.cpu_percent blocks for the interval to measure correctly
                return psutil.cpu_percent(interval=interval)
            except Exception:
                pass
        # Fallback: use load average on Unix-like systems, scaled to CPU count
        if hasattr(os, 'getloadavg'):
            try:
                load1 = os.getloadavg()[0]
                cpus = os.cpu_count() or 1
                return min(100.0, (load1 / cpus) * 100.0)
            except Exception:
                pass
        # Windows fallback: try wmic
        if platform.system().lower().startswith('win'):
            try:
                proc = subprocess.run(['wmic', 'cpu', 'get', 'loadpercentage'], capture_output=True, text=True)
                out = proc.stdout.strip().splitlines()
                if len(out) >= 2:
                    # take first numeric value
                    for line in out[1:]:
                        line = line.strip()
                        if line:
                            try:
                                return float(line)
                            except Exception:
                                pass
            except Exception:
                pass
        # Last resort: return 0.0
        return 0.0

    # Memory usage
    def get_memory_info():
        if psutil:
            try:
                v = psutil.virtual_memory()
                return int(v.total), int(v.used), float(v.percent)
            except Exception:
                pass
        # Linux: read /proc/meminfo
        if platform.system().lower().startswith('linux'):
            try:
                meminfo = {}
                with open('/proc/meminfo', 'r') as f:
                    for line in f:
                        parts = line.split(':')
                        if len(parts) < 2:
                            continue
                        key = parts[0].strip()
                        val = parts[1].strip().split()[0]
                        meminfo[key] = int(val)  # in kB
                total_k = meminfo.get('MemTotal')
                avail_k = meminfo.get('MemAvailable', meminfo.get('MemFree'))
                if total_k and avail_k is not None:
                    total = total_k * 1024
                    available = avail_k * 1024
                    used = total - available
                    percent = (used / total) * 100.0 if total else 0.0
                    return int(total), int(used), float(percent)
            except Exception:
                pass
