        if platform.system().lower().startswith('win'):
            try:
                import ctypes

                class MEMORYSTATUSEX(ctypes.Structure):
                    _fields_ = [
                        ('dwLength', ctypes.c_ulong),
                        ('dwMemoryLoad', ctypes.c_ulong),
                        ('ullTotalPhys', ctypes.c_ulonglong),
                        ('ullAvailPhys', ctypes.c_ulonglong),
                        ('ullTotalPageFile', ctypes.c_ulonglong),
                        ('ullAvailPageFile', ctypes.c_ulonglong),
                        ('ullTotalVirtual', ctypes.c_ulonglong),
                        ('ullAvailVirtual', ctypes.c_ulonglong),
                        ('sullAvailExtendedVirtual', ctypes.c_ulonglong),
                    ]

                stat = MEMORYSTATUSEX()
                stat.dwLength = ctypes.sizeof(MEMORYSTATUSEX)
                ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(stat))
                total = int(stat.ullTotalPhys)
                avail = int(stat.ullAvailPhys)
                used = total - avail
                percent = float(stat.dwMemoryLoad)
                return total, used, percent
            except Exception:
                pass
        # Generic fallback: unknown -> zero values
        return 0, 0, 0.0

    # Disk usage
    def get_disk_info(path):
        try:
            du = shutil.disk_usage(path)
            total = int(du.total)
            used = int(du.used)
            percent = (used / total) * 100.0 if total else 0.0
            return total, used, percent
        except Exception:
            # Try root fallback
            try:
                du = shutil.disk_usage(os.path.sep)
                total = int(du.total)
                used = int(du.used)
                percent = (used / total) * 100.0 if total else 0.0
                return total, used, percent
            except Exception:
                return 0, 0, 0.0

    # Collect metrics
    cpu_percent = get_cpu_percent(interval)
    mem_total, mem_used, mem_percent = get_memory_info()
    disk_total, disk_used, disk_percent = get_disk_info(path)

    # Build rows for the table
    rows = [
        ['Metric', 'Usage'],
        ['CPU Usage', f"{cpu_percent:.1f}%"],
        ['Memory Usage', f"{mem_percent:.1f}% ({format_bytes(mem_used)} / {format_bytes(mem_total)})"],
        [f"Disk Usage ({path})", f"{disk_percent:.1f}% ({format_bytes(disk_used)} / {format_bytes(disk_total)})"],
    ]

    # Minimal ASCII table renderer (txttable-like)
    class SimpleTxtTable:
        def __init__(self, rows):
            # rows: list of lists of strings
            self.rows = [[str(cell) for cell in row] for row in rows]

        def draw(self):
            # compute column widths
            cols = max(len(r) for r in self.rows)
            widths = [0] * cols
            for r in self.rows:
                for i, c in enumerate(r):
                    widths[i] = max(widths[i], len(c))
            # build horizontal separator
            sep_parts = ['-' * (w + 2) for w in widths]
            sep = '+' + '+'.join(sep_parts) + '+'
            # render rows
            out_lines = []
            out_lines.append(sep)
            for ri, r in enumerate(self.rows):
                parts = []
                for i in range(cols):
                    cell = r[i] if i < len(r) else ''
                    parts.append(' ' + cell.ljust(widths[i]) + ' ')
                out_lines.append('|' + '|'.join(parts) + '|')
                # header separator after first row
                if ri == 0:
                    out_lines.append(sep)
            out_lines.append(sep)
            return '\n'.join(out_lines)

    table = SimpleTxtTable(rows)
    return table.draw()


# Example usage:
if __name__ == '__main__':
    print(generate_system_usage_table('/'))
