Install required packages if you don't already have them:
- For .xlsx support: pip install openpyxl
- For .xls support: pip install xlrd

Code:

```python
import os
import csv
from typing import Optional

def convert_excel_to_csv(src_path: str, dst_path: Optional[str] = None, sheet_name: Optional[str] = None, encoding: str = 'utf-8') -> str:
    """
    Convert an Excel file (.xlsx or .xls) to CSV.

    Parameters:
    - src_path: Path to the source Excel file (.xlsx or .xls).
    - dst_path: Optional path to the destination CSV file. If None, a CSV with the same
                basename as src_path is created in the same directory (extension .csv).
    - sheet_name: Optional sheet name (string) or sheet index (int) to convert. If None,
                  the first sheet is used.
    - encoding: Encoding used to write the CSV file (default 'utf-8').

    Returns:
    - The path to the created CSV file.

    Raises:
    - FileNotFoundError if src_path does not exist.
    - ValueError for unsupported extension or missing sheet.
    - ImportError if required library for a given extension is not available.
    """
    if not os.path.isfile(src_path):
        raise FileNotFoundError(f"Source file not found: {src_path}")

    base, ext = os.path.splitext(src_path)
    ext = ext.lower()

    if dst_path is None:
        dst_path = base + '.csv'

    # Helper to ensure directory exists for the destination
    dst_dir = os.path.dirname(dst_path)
    if dst_dir and not os.path.exists(dst_dir):
        os.makedirs(dst_dir, exist_ok=True)

    if ext in ('.xlsx', '.xlsm', '.xltx', '.xltm'):
        # Use openpyxl to read .xlsx and related formats
        try:
            import openpyxl
        except ImportError as e:
            raise ImportError("openpyxl is required to read .xlsx files. Install with: pip install openpyxl") from e

        wb = openpyxl.load_workbook(src_path, read_only=True, data_only=True)
        # Determine sheet
        if sheet_name is None:
            ws = wb[wb.sheetnames[0]]
        else:
            if isinstance(sheet_name, int):
                try:
                    ws = wb[wb.sheetnames[sheet_name]]
                except Exception as e:
                    raise ValueError(f"Invalid sheet index: {sheet_name}") from e
            else:
                if sheet_name not in wb.sheetnames:
                    raise ValueError(f"Sheet '{sheet_name}' not found in workbook.")
                ws = wb[sheet_name]

        with open(dst_path, 'w', newline='', encoding=encoding) as csvfile:
            writer = csv.writer(csvfile)
            for row in ws.iter_rows(values_only=True):
                # Convert None => '' to avoid writing 'None'
                writer.writerow([("" if cell is None else cell) for cell in row])

        wb.close()
        return dst_path

    elif ext == '.xls':
        # Use xlrd to read .xls files
        try:
            import xlrd
        except ImportError as e:
            raise ImportError("xlrd is required to read .xls files. Install with: pip install xlrd") from e

        book = xlrd.open_workbook(src_path)
        # Determine sheet
        if sheet_name is None:
            sheet = book.sheet_by_index(0)
        else:
            if isinstance(sheet_name, int):
                try:
                    sheet = book.sheet_by_index(sheet_name)
                except Exception as e:
                    raise ValueError(f"Invalid sheet index: {sheet_name}") from e
            else:
                try:
                    sheet = book.sheet_by_name(sheet_name)
                except Exception as e:
                    raise ValueError(f"Sheet '{sheet_name}' not found in workbook.") from e

        def cell_to_python_value(cell, datemode):
            ctype = cell.ctype
            value = cell.value
            # xlrd types: 0 empty, 1 text, 2 number, 3 date, 4 boolean, 5 error
            if ctype == xlrd.XL_CELL_EMPTY or ctype == xlrd.XL_CELL_BLANK:
                return ""
            if ctype == xlrd.XL_CELL_TEXT:
                return value
            if ctype == xlrd.XL_CELL_NUMBER:
                # keep Python numeric (int if appropriate)
                if float(value).is_integer():
                    return int(value)
                return value
            if ctype == xlrd.XL_CELL_DATE:
                try:
                    dt = xlrd.xldate_as_datetime(value, datemode)
                    # Write ISO format datetime/date string
                    return dt.isoformat()
                except Exception:
                    return value
            if ctype == xlrd.XL_CELL_BOOLEAN:
                return bool(value)
            if ctype == xlrd.XL_CELL_ERROR:
                return ""
            return value

        datemode = book.datemode
        with open(dst_path, 'w', newline='', encoding=encoding) as csvfile:
            writer = csv.writer(csvfile)
            for r in range(sheet.nrows):
                row = []
                for c in range(sheet.ncols):
                    cell = sheet.cell(r, c)
                    row.append(cell_to_python_value(cell, datemode))
                writer.writerow(row)

        return dst_path

    else:
        raise ValueError(f"Unsupported file extension: {ext}. Supported: .xlsx, .xls")

# Example usage:
# convert_excel_to_csv('data/myfile.xlsx')  # writes data/myfile.csv
# convert_excel_to_csv('data/book.xls', 'out/book_sheet1.csv', sheet_name=0)
```

Notes:
- For .xlsx files the function uses openpyxl (reads cell values, including formulas evaluated values if the workbook contains them saved).
- For .xls files the function uses xlrd.
- If you want to convert all sheets to separate CSV files, you can loop through workbook.sheetnames and call this function repeatedly (or modify it to export all sheets).
