Python function (self-contained):


def histogram_grayscale(image, bins=256):
    """
    Compute a histogram of grayscale pixel values (0..255 by default).
    Accepts:
      - a filesystem path (str) to an image file,
      - a PIL.Image.Image,
      - a numpy array (2D or flattened), or
      - bytes/bytearray of grayscale pixel values.
    Returns:
      - list of length `bins` with counts for each intensity bin.
    Behavior:
      - Tries to use a nimpy-backed module named `imhist_nim` if nimpy is installed
        and that module is importable. If not available, falls back to a Python
        implementation (numpy-based if numpy is installed, otherwise pure-Python).
    Note:
      - If passing raw bytes/bytearray you are expected to supply exactly the
        pixel values. No width/height checks are performed in that case.
    """
    # Helper: convert various inputs to a flat list/1D numpy array of uint8-like ints
    def _to_flat_uint8_values(obj):
        # If filepath
        try:
            from PIL import Image
        except Exception:
            Image = None

        try:
            import numpy as _np
        except Exception:
            _np = None

        # Path
        if isinstance(obj, str):
            if Image is None:
                raise RuntimeError("Pillow (PIL) is required to open image files.")
            img = Image.open(obj).convert("L")
            arr = None
            if _np is not None:
                arr = _np.asarray(img, dtype=_np.uint8)
                return arr.ravel()
            else:
                return list(img.getdata())

        # PIL Image
        if Image is not None and isinstance(obj, Image.Image):
            img = obj.convert("L")
            if _np is not None:
                arr = _np.asarray(img, dtype=_np.uint8)
                return arr.ravel()
            else:
                return list(img.getdata())

        # numpy array
        if _np is not None and isinstance(obj, _np.ndarray):
            arr = obj
            # If 2D convert to grayscale if necessary; if float, scale/clamp to 0..255
            if arr.ndim == 2:
                # assume already grayscale
                arru = arr.astype(_np.uint8, copy=False)
                return arru.ravel()
            elif arr.ndim == 3 and arr.shape[2] in (3, 4):
                # convert RGB(A) to luminance (simple average)
                rgb = arr[..., :3].astype(_np.float32)
                lum = rgb.mean(axis=2)
                return lum.astype(_np.uint8).ravel()
            else:
                return arr.ravel().astype(_np.uint8)

        # bytes / bytearray
        if isinstance(obj, (bytes, bytearray)):
            # treat each byte as a pixel value 0..255
            # return as list of ints
            return list(obj)

        # list/tuple of ints
        if isinstance(obj, (list, tuple)):
            return list(obj)

        raise TypeError("Unsupported image input type: {}".format(type(obj)))

    # Try nimpy + compiled Nim module first
    try:
        import nimpy  # only to detect nimpy presence
        try:
            import imhist_nim  # this is the expected compiled Nim extension module
            pixels = _to_flat_uint8_values(image)
            # imhist_nim.histogram should accept a sequence of ints (0..255) and bins param
            hist = imhist_nim.histogram(pixels, bins)
            # Ensure returned as a regular Python list of ints
            return list(hist)
        except Exception:
            # fallback to python implementation if nimpy or module not available or call fails
            pass
    except ImportError:
        # nimpy not installed; proceed to python fallback
        pass

    # Python fallback: try numpy for speed, otherwise pure Python
    try:
        import numpy as np
        pixels = _to_flat_uint8_values(image)
        # If we got a numpy array already, ensure it's a 1D uint8 view
        if isinstance(pixels, np.ndarray):
            arr = pixels.astype(np.uint8, copy=False).ravel()
            # Use bincount
            hist = np.bincount(arr, minlength=bins)
            return hist[:bins].astype(int).tolist()
        else:
            # list-like
            arr = np.asarray(pixels, dtype=np.uint8)
            hist = np.bincount(arr, minlength=bins)
            return hist[:bins].astype(int).tolist()
    except Exception:
        # Pure Python fallback
        pixels = _to_flat_uint8_values(image)
        hist = [0] * bins
        for v in pixels:
            try:
                iv = int(v) & 0xFF
            except Exception:
                continue
            if 0 <= iv < bins:
                hist[iv] += 1
        return hist

