Here's a single self-contained Python function that uses the requests library to fetch a GitHub user's data, normalizes all string data (keys and values) to ASCII, and returns the normalized dictionary. It raises an HTTPError for non-200 responses.

```python
def get_github_user_normalized(username, token=None, timeout=10):
    """
    Retrieve GitHub user info for `username`, normalize all string data to ASCII,
    and return a dictionary of the normalized data.

    Parameters:
    - username: str - GitHub username to fetch
    - token: str or None - optional GitHub personal access token for higher rate limits
    - timeout: int or float - request timeout in seconds (default 10)

    Returns:
    - dict: normalized user data (all string keys and values converted to ASCII)

    Raises:
    - requests.HTTPError: on non-2xx responses
    - requests.RequestException: on other request errors
    - ValueError: if response JSON cannot be decoded
    """
    import requests
    import unicodedata

    def to_ascii(s):
        """Normalize a Python str to ASCII by removing diacritics and non-ASCII chars."""
        if not isinstance(s, str):
            return s
        return unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii")

    def normalize(obj):
        """Recursively normalize strings in nested structures (dicts, lists, tuples, sets)."""
        if isinstance(obj, str):
            return to_ascii(obj)
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                new_key = to_ascii(k) if isinstance(k, str) else k
                new[new_key] = normalize(v)
            return new
        if isinstance(obj, list):
            return [normalize(i) for i in obj]
        if isinstance(obj, tuple):
            return tuple(normalize(i) for i in obj)
        if isinstance(obj, set):
            # Sets require hashable items; converting each item and discarding unhashable results
            normalized_items = []
            for i in obj:
                ni = normalize(i)
                try:
                    hash(ni)
                except TypeError:
                    # If unhashable (e.g. dict), skip it; sets typically won't be encountered in JSON
                    continue
                normalized_items.append(ni)
            return set(normalized_items)
        return obj  # numbers, booleans, None

    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "github-user-normalizer/1.0",
    }
    if token:
        headers["Authorization"] = f"token {token}"

    url = f"https://api.github.com/users/{username}"
    resp = requests.get(url, headers=headers, timeout=timeout)
    resp.raise_for_status()  # will raise HTTPError for 4xx/5xx

    data = resp.json()  # may raise ValueError if not JSON
    return normalize(data)
