def mean_variance_numpy(L):
    """
    Compute mean and population variance of all numeric elements in nested list L using numpy.
    Returns (mean, variance). If no numeric elements are found returns (float('nan'), float('nan')).

    Requires numpy to be installed.
    """
    try:
        import numpy as np
    except ImportError as e:
        raise ImportError("numpy is required for mean_variance_numpy; install it or use the pure-Python fallback.") from e

    def iter_numbers(x):
        if isinstance(x, (list, tuple)):
            for y in x:
                yield from iter_numbers(y)
        else:
            yield x

    arr = np.fromiter((float(x) for x in iter_numbers(L)), dtype=float)
    if arr.size == 0:
        return float('nan'), float('nan')
    mean = float(arr.mean())
    var = float(arr.var())  # population variance (ddof=0)
    return mean, var


def mean_variance_pure(L):
    """
    Compute mean and population variance of all numeric elements in nested list L using pure Python
    (Welford's online algorithm). Returns (mean, variance). If no numeric elements are found returns (nan, nan).
    """
    import math

    def iter_numbers(x):
        if isinstance(x, (list, tuple)):
            for y in x:
                yield from iter_numbers(y)
        else:
            yield x

    n = 0
    mean = 0.0
    M2 = 0.0
    for val in iter_numbers(L):
        x = float(val)
        n += 1
        delta = x - mean
        mean += delta / n
        M2 += delta * (x - mean)

    if n == 0:
        return float('nan'), float('nan')
    variance = M2 / n  # population variance
    return mean, variance


# Convenience wrapper: try numpy first, fall back to pure Python
def mean_and_variance(L, prefer_numpy=True):
    """
    Compute mean and population variance of all numeric elements in L.
    If prefer_numpy is True, attempts to use numpy and falls back to pure-Python if numpy is not available.
    Returns (mean, variance).
    """
    if prefer_numpy:
        try:
            return mean_variance_numpy(L)
        except ImportError:
            return mean_variance_pure(L)
    else:
        return mean_variance_pure(L)


# Example usage:
if __name__ == "__main__":
