    - accepts nested lists/tuples/numpy arrays of arbitrary depth,
    - raises ValueError if no elements are found,
    - raises TypeError if a non-numeric element is encountered,
    - attempts to use 'cipy' if present, then 'scipy.stats.iqr', else uses numpy percentiles.

    Returns:
      float: the IQR of the values in L.
    """
    import importlib
    from numbers import Number
    import numpy as np

    def _flatten(obj):
        # recursively flatten lists/tuples/numpy arrays
        if isinstance(obj, (list, tuple, np.ndarray)):
            for item in obj:
                yield from _flatten(item)
        else:
            yield obj

    flat = list(_flatten(L))
    if not flat:
        raise ValueError("Input contains no elements.")

    nums = []
    for x in flat:
        if isinstance(x, Number):
            nums.append(float(x))
        else:
