    arr = np.asarray(nums)
    # Try to use 'cipy' if it exists (per request), then scipy, else fallback to numpy
    try:
        cipy = importlib.import_module('cipy')
        # try common locations for iqr
        if hasattr(cipy, 'iqr'):
            return float(cipy.iqr(arr))
        stats = getattr(cipy, 'stats', None)
        if stats and hasattr(stats, 'iqr'):
            return float(stats.iqr(arr))
    except Exception:
        pass

    try:
        scipy_stats = importlib.import_module('scipy.stats')
        return float(scipy_stats.iqr(arr))
    except Exception:
        q75 = np.percentile(arr, 75)
        q25 = np.percentile(arr, 25)
