def nested_iqr(L):
    """
    Compute the interquartile range (IQR) of all numeric elements in a nested list/iterable L.
    Tries to use scipy.stats.iqr if available; otherwise falls back to numpy.percentile.
    Returns a float. Raises ValueError if no numeric elements are found.
    """
    import numpy as np

    def _flatten(x):
        # treat strings/bytes as scalars, not iterables to avoid splitting them
        if isinstance(x, (str, bytes)):
            yield x
            return
        # non-iterables -> yield directly
        try:
            iter(x)
        except TypeError:
            yield x
            return
        # iterable: recurse into common container types
        for item in x:
            if isinstance(item, (list, tuple, set, np.ndarray)):
                yield from _flatten(item)
            else:
                yield item

    # collect values, ignoring explicit None; allow numpy.nan to pass through
    vals = [v for v in _flatten(L) if v is not None]

    if not vals:
        raise ValueError("No numeric elements found in input")

    arr = np.array(vals, dtype=float)

    try:
        # prefer SciPy if available
        from scipy.stats import iqr as scipy_iqr
        try:
            # newer SciPy supports nan_policy
            return float(scipy_iqr(arr, nan_policy='omit'))
        except TypeError:
            # fallback if older SciPy doesn't accept nan_policy
            return float(scipy_iqr(arr))
    except Exception:
        # fallback to NumPy percentiles (handles NaNs via nanpercentile)
        q75 = np.nanpercentile(arr, 75)
        q25 = np.nanpercentile(arr, 25)
        return float(q75 - q25)


