from datetime import datetime
from typing import List, Dict, Any
try:
    # Python 3.9+
    from zoneinfo import ZoneInfo
    _USE_ZONEINFO = True
except Exception:
    ZoneInfo = None
    _USE_ZONEINFO = False

try:
    import pytz
    _HAVE_PYTZ = True
except Exception:
    pytz = None
    _HAVE_PYTZ = False


def _parse_iso_datetime(s: str) -> datetime:
    """
    Parse an ISO8601-like datetime string to a datetime instance.
    Accepts 'Z' as UTC. Does not require external dateutil.
    """
    if not isinstance(s, str):
        raise TypeError("Expected string for datetime parsing")
    # Handle 'Z' suffix (UTC)
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    # Python's fromisoformat supports offsets like +00:00
    return datetime.fromisoformat(s)


def analyze_publication_hours(
    articles: List[Dict[str, Any]],
    target_tz: str = "UTC",
    assume_naive_tz: str = "UTC"
) -> Dict[Any, Dict[str, Any]]:
    """
    Analyze publication times of articles.

    Parameters:
    - articles: list of dicts, each with keys 'published_time' (str or datetime) and 'category'.
    - target_tz: timezone name to convert published_time into (IANA name, e.g., 'Europe/London' or 'UTC').
    - assume_naive_tz: timezone name to assume for naive datetimes or naive strings.

    Returns: dict mapping category -> {'count': int, 'mean_hour': float, 'min_hour': int, 'max_hour': int}
    """
    if not isinstance(articles, list):
        raise TypeError("articles must be a list of dicts")

    # Prepare timezone objects
    def get_tz(tzname: str):
        if _USE_ZONEINFO:
            try:
                return ZoneInfo(tzname)
            except Exception as e:
                raise ValueError(f"Unknown timezone for zoneinfo: {tzname}") from e
        elif _HAVE_PYTZ:
            try:
                return pytz.timezone(tzname)
            except Exception as e:
                raise ValueError(f"Unknown timezone for pytz: {tzname}") from e
        else:
            raise RuntimeError(
                "No timezone implementation available. Install Python 3.9+ (zoneinfo) or pytz."
            )

    target_tz_obj = get_tz(target_tz)
    assume_naive_tz_obj = get_tz(assume_naive_tz)

    # Helper to ensure a datetime is timezone-aware and converted to target_tz_obj
    def to_target_dt(dt_or_str):
        if isinstance(dt_or_str, str):
            dt = _parse_iso_datetime(dt_or_str)
        elif isinstance(dt_or_str, datetime):
            dt = dt_or_str
        else:
            raise TypeError("published_time must be a str or datetime")

        # If naive, localize/assign assume_naive_tz
        if dt.tzinfo is None:
            if _USE_ZONEINFO:
                # zoneinfo: attach zone with replace(tzinfo=...)
                dt = dt.replace(tzinfo=assume_naive_tz_obj)
                # then convert to target zone
                return dt.astimezone(target_tz_obj)
            else:
                # pytz: localize then convert
                dt = assume_naive_tz_obj.localize(dt)
                return dt.astimezone(target_tz_obj)
        else:
            # dt already tz-aware
            return dt.astimezone(target_tz_obj)

    # Group hours by category
    groups = {}  # category -> list of hours (ints 0-23)
    for item in articles:
        if not isinstance(item, dict):
            raise TypeError("Each article must be a dict")
        if 'published_time' not in item or 'category' not in item:
            raise ValueError("Each article dict must contain 'published_time' and 'category' keys")
        category = item['category']
        published_time = item['published_time']
        dt_converted = to_target_dt(published_time)
        hour = dt_converted.hour
        groups.setdefault(category, []).append(hour)

    # Compute stats
    results = {}
    for cat, hours in groups.items():
        if not hours:
            continue
        count = len(hours)
        mean_hour = sum(hours) / count
        min_hour = min(hours)
        max_hour = max(hours)
        results[cat] = {
            'count': count,
            'mean_hour': mean_hour,
            'min_hour': min_hour,
            'max_hour': max_hour
        }
    return results
```

