except Exception:
    _HAS_ZONEINFO = False

try:
    import pytz
    _HAS_PYTZ = True
except Exception:
    _HAS_PYTZ = False

def analyze_publication_hours(
    articles: List[Dict[str, Any]],
    target_tz: str = "UTC"
) -> Dict[str, Dict[str, Optional[float]]]:
    """
    Analyze publication times.

    Args:
      articles: list of dicts, each with keys:
        - 'published_time': a datetime or an ISO-format string (e.g. "2021-05-01T12:34:56Z" or with offset)
        - 'category': grouping key (string)
      target_tz: timezone name (IANA, e.g. "UTC", "Europe/Berlin")

    Returns:
      dict mapping category -> dict with keys:
        - 'count': int number of articles in category
        - 'mean_hour': float arithmetic mean of hours (0-23) or None if no valid times
        - 'min_hour': int minimum hour or None
        - 'max_hour': int maximum hour or None
    """

    def _parse_datetime(value) -> Optional[datetime]:
        if value is None:
            return None
        if isinstance(value, datetime):
            dt = value
        elif isinstance(value, str):
            s = value.strip()
            # Accept trailing Z (UTC)
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                # fromisoformat handles "YYYY-MM-DDTHH:MM:SS" and offset forms
                dt = datetime.fromisoformat(s)
            except Exception:
                # As a last resort, try parsing common format without offset
                try:
                    dt = datetime.strptime(s, "%Y-%m-%dT%H:%M:%S")
                except Exception:
                    return None
        else:
            return None
        return dt

    # Prepare timezone conversion functions
    if _HAS_ZONEINFO:
        def _to_target(dt: datetime) -> datetime:
            # Treat naive datetimes as UTC
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt.astimezone(ZoneInfo(target_tz))
    elif _HAS_PYTZ:
        tz_target = pytz.timezone(target_tz)
        def _to_target(dt: datetime) -> datetime:
            if dt.tzinfo is None:
                # assume naive is UTC
                dt = pytz.UTC.localize(dt)
            return dt.astimezone(tz_target)
    else:
        # No timezone library available: perform naive conversion assuming UTC and no DST handling
        def _to_target(dt: datetime) -> datetime:
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            # If target_tz is "UTC" or equivalent, this is fine; otherwise we cannot convert properly
            if target_tz.upper() not in ("UTC", "Z"):
                # best-effort: return the UTC time but warn by raising ValueError
                raise RuntimeError("No timezone support available (install Python 3.9+ or pytz).")
            return dt.astimezone(timezone.utc)

    # Group hours by category
    groups: Dict[str, List[int]] = {}

    for art in articles:
        if not isinstance(art, dict):
            continue
        cat = art.get("category")
        if cat is None:
            continue
        raw = art.get("published_time")
        dt = _parse_datetime(raw)
        if dt is None:
            continue
        try:
            dt_t = _to_target(dt)
        except Exception:
            # skip if conversion failed
            continue
        hour = dt_t.hour
        groups.setdefault(cat, []).append(hour)

    # Compute stats
    result: Dict[str, Dict[str, Optional[float]]] = {}
    for cat, hours in groups.items():
        if not hours:
            result[cat] = {"count": 0, "mean_hour": None, "min_hour": None, "max_hour": None}
