def most_common_per_column(csv_path):
    """
    Return a dict mapping column name -> most common value in that column.
    Ties are broken by alphabetical order (first wins).
    If the CSV is empty (no header or no data rows), returns {}.

    csv_path: path to CSV file (expects a header row with column names).
    """
    from collections import Counter
    import csv

    # Quick check for emptiness / header presence
    try:
        with open(csv_path, 'r', encoding='utf-8', newline='') as f:
            # Find first non-empty line (to allow leading blank lines)
            first_line = None
            for line in f:
                if line.strip():
                    first_line = line
                    break
            if first_line is None:
                return {}  # totally empty file
    except FileNotFoundError:
        raise

    # Try to use numpy if available (optional). If not, fall back to csv.DictReader.
    try:
        import numpy as np
        # Use numpy to read; require at least one data row
        try:
            data = np.genfromtxt(csv_path, delimiter=',', dtype=str, names=True, encoding='utf-8')
        except Exception:
            # If numpy fails to parse, fall back to csv
            raise ImportError

        # If genfromtxt returns a scalar (single row) make it 1D array
        if data.size == 0:
            return {}
        # If data is a 0-d structured array (single row), np.atleast_1d will help
        data = np.atleast_1d(data)
        colnames = data.dtype.names
        if not colnames:
            return {}

        result = {}
        for col in colnames:
            col_values = data[col].astype(str)  # ensure strings
            # Exclude empty strings that come from missing entries? Keep them as values.
            # Build counts
            # Use python counter for tie-breaking easily
            cnt = Counter(col_values)
            if not cnt:
                continue
            max_count = max(cnt.values())
            candidates = [v for v, c in cnt.items() if c == max_count]
            chosen = sorted(candidates)[0]
            result[col] = chosen
        return result

    except Exception:
        # Fall back to robust csv.DictReader + Counter approach
        with open(csv_path, 'r', encoding='utf-8', newline='') as f:
            reader = csv.DictReader((row for row in f if row.strip()))
            if not reader.fieldnames:
                return {}
            counters = {name: Counter() for name in reader.fieldnames}
            rows_seen = False
            for row in reader:
                rows_seen = True
                for name in reader.fieldnames:
                    # csv.DictReader returns None for missing fields; convert to empty string
                    val = row.get(name, '')
                    # Keep the raw string value (could be empty string)
                    counters[name][val] += 1
            if not rows_seen:
                return {}
            result = {}
            for name, counter in counters.items():
                if not counter:
                    continue
                max_count = max(counter.values())
                candidates = [v for v, c in counter.items() if c == max_count]
                chosen = sorted(candidates)[0]
                result[name] = chosen
            return result
