def sum_squares_by_lengths(list_of_lists, POSSIBLE_NUMBERS=None, allow_truncate=False):
    """
    For each list in list_of_lists compute the sum of squares of the first k numbers
    from POSSIBLE_NUMBERS, where k = len(list).
    - POSSIBLE_NUMBERS: an iterable of numbers (default: 1..100).
    - allow_truncate: if True and k > len(POSSIBLE_NUMBERS), use all available numbers;
                      if False, raise ValueError in that case.
    Returns a list of sums (float when numpy is used, int with the pure-Python fallback).
    """
    try:
        import numpy as np
    except ImportError:
        np = None

    if POSSIBLE_NUMBERS is None:
        POSSIBLE_NUMBERS = range(1, 101)

    # Use numpy if available
    if np is not None:
        arr = np.array(list(POSSIBLE_NUMBERS), dtype=float)
        sq = arr * arr
        cums = np.cumsum(sq)
        n = arr.size
        results = []
        for lst in list_of_lists:
            k = len(lst)
            if k == 0:
                results.append(0.0)
            elif k > n:
                if allow_truncate:
                    results.append(float(cums[-1]))
                else:
                    raise ValueError(f"Need first {k} numbers but POSSIBLE_NUMBERS has only {n}")
            else:
                results.append(float(cums[k-1]))
        return results

    # Pure-Python fallback
    sqs = [x * x for x in POSSIBLE_NUMBERS]
    cums = []
    total = 0
    for s in sqs:
        total += s
        cums.append(total)
    n = len(cums)
    results = []
    for lst in list_of_lists:
        k = len(lst)
        if k == 0:
            results.append(0)
        elif k > n:
            if allow_truncate:
                results.append(cums[-1])
            else:
                raise ValueError(f"Need first {k} numbers but POSSIBLE_NUMBERS has only {n}")
        else:
            results.append(cums[k-1])
    return results

