def calculate_xyz_stats(d):
    """
    Calculate mean, sum, max, min, and standard deviation for keys 'x', 'y', 'z'
    from a list of dictionaries `d`.

    Parameters:
      d (list of dict): e.g. [{'x':1,'y':2,'z':3}, {'x':4,'y':None,'z':6}, ...]

    Returns:
      dict: {'x': {'mean':..., 'sum':..., 'max':..., 'min':..., 'std':...}, ...}
            Missing/empty columns return None for mean/max/min/std and 0.0 for sum.
    """
    keys = ['x', 'y', 'z']

    # Try to use pandas if available
    try:
        import pandas as pd
        df = pd.DataFrame(d)
        result = {}
        for k in keys:
            if k in df:
                col = df[k].dropna().astype(float)
                if col.empty:
                    result[k] = {'mean': None, 'sum': 0.0, 'max': None, 'min': None, 'std': None}
                else:
                    result[k] = {
                        'mean': float(col.mean()),
                        'sum': float(col.sum()),
                        'max': float(col.max()),
                        'min': float(col.min()),
                        # pandas.Series.std default ddof=1 (sample std). Return None if single value.
                        'std': (float(col.std(ddof=1)) if col.size > 1 else None)
                    }
            else:
                result[k] = {'mean': None, 'sum': 0.0, 'max': None, 'min': None, 'std': None}
        return result

    except Exception:
        # Fallback: pure Python implementation using statistics
        import statistics
        result = {}
        for k in keys:
            vals = []
            for item in d:
                # item may not be a dict or may not contain the key
                try:
                    v = item.get(k)
                except Exception:
                    continue
                if v is None:
                    continue
                try:
                    vals.append(float(v))
                except Exception:
                    # ignore non-numeric values
                    continue
            if not vals:
                result[k] = {'mean': None, 'sum': 0.0, 'max': None, 'min': None, 'std': None}
            else:
                result[k] = {
                    'mean': statistics.mean(vals),
                    'sum': float(sum(vals)),
                    'max': max(vals),
                    'min': min(vals),
                    # statistics.stdev uses sample std (ddof=1). Return None if single value.
                    'std': (statistics.stdev(vals) if len(vals) > 1 else None)
                }
        return result

