from collections import Counter

def count_xyz(d: List[Dict[str, Any]]) -> Dict[str, Dict[Any, int]]:
    """
    Count occurrences of values for keys "x", "y", and "z" in a list of dictionaries.

    Returns a dict mapping each key ("x","y","z") to a dict of value -> count.
    Missing keys in some dictionaries are ignored.

    Example:
      d = [{'x':1,'y':2}, {'x':1,'z':3}, {'y':2,'z':3,'x':4}]
      count_xyz(d) -> {'x': {1: 2, 4: 1}, 'y': {2: 2}, 'z': {3: 2}}
    """
    keys = ("x", "y", "z")

    # Try to use pandas if available (faster for large inputs)
    try:
        import pandas as pd  # type: ignore
        if not isinstance(d, list):
            raise ValueError("Input must be a list of dictionaries.")
        df = pd.DataFrame(d)
        result: Dict[str, Dict[Any, int]] = {}
        for k in keys:
            if k in df.columns:
                # value_counts ignores NaN by default; convert to dict
                vc = df[k].value_counts(dropna=True)
                # Convert pandas Index keys to Python native types (via to_dict)
                result[k] = {k2: int(v2) for k2, v2 in vc.to_dict().items()}
            else:
                result[k] = {}
        return result

    except Exception:
        # Fallback: pure Python implementation (no external deps)
        counters = {k: Counter() for k in keys}
        for item in d:
            if not isinstance(item, dict):
                continue
            for k in keys:
                if k in item:
                    val = item[k]
                    # Treat None as "missing" and do not count it:
                    if val is not None:
                        counters[k][val] += 1
        # Convert Counter to plain dict
        return {k: dict(counters[k]) for k in keys}


