```python
import numbers
from typing import Any, List, Union, Optional, Tuple
import seaborn as sns
import matplotlib.pyplot as plt

def extract_and_plot_json_numbers(
    json_obj: Any,
    path: Union[str, List[str]],
    plot_type: str = "hist",
    bins: int = 30,
    kde: bool = False,
    figsize: Tuple[float, float] = (8, 6),
    title: Optional[str] = None,
    xlabel: Optional[str] = None,
    ylabel: Optional[str] = None,
    color: Optional[str] = None,
    alpha: float = 0.6,
    save_path: Optional[str] = None,
) -> Tuple[List[float], plt.Axes]:
    """
    Extract numeric values from a nested JSON-like structure following `path`
    and visualize them with seaborn.

    Parameters:
    - json_obj: The JSON-like object (nested dicts/lists).
    - path: Dot-separated string (e.g. "a.b.c") or list of keys (e.g. ["a","b","c"])
            The special key "*" can be used to iterate over all values of a dict level.
    - plot_type: One of {"hist", "kde", "box", "violin", "ecdf"}. Default "hist".
    - bins: Number of bins for histogram (only for hist).
    - kde: If True and plot_type == "hist", overlay a KDE curve.
    - figsize: Matplotlib figure size.
    - title, xlabel, ylabel: Plot labels. If None, sensible defaults are used.
    - color: Color passed to seaborn plotting function.
    - alpha: Transparency for applicable plots.
    - save_path: If provided, save the figure to this path.

    Returns:
    - (values, ax) where values is the list of extracted numeric values (floats),
      and ax is the matplotlib Axes containing the plot.

    Notes:
    - Numeric means instances of numbers.Number but booleans are excluded.
    - If no numeric values are found a ValueError is raised.
    - Requires seaborn and matplotlib to be installed.

    Example:
    data = {"groups": [{"scores": [1,2,3]}, {"scores": [4,5]}]}
    vals, ax = extract_and_plot_json_numbers(data, "groups.*.scores", plot_type="hist")
    """
    # Normalize path to list of keys
    if isinstance(path, str):
        keys = path.split(".") if path else []
    else:
        keys = list(path) if path is not None else []

    values: List[float] = []

    def _gather(node: Any, remaining_keys: List[str]) -> None:
        # If there are no more keys to follow, collect numeric leaves under node
        if not remaining_keys:
            if isinstance(node, dict):
                for v in node.values():
                    _gather(v, [])
            elif isinstance(node, list):
                for item in node:
                    _gather(item, [])
            else:
                if isinstance(node, numbers.Number) and not isinstance(node, bool):
                    # convert to float for consistent plotting
                    try:
                        values.append(float(node))
                    except Exception:
                        pass
            return

        # There are still keys left to traverse
        key = remaining_keys[0]
        rest = remaining_keys[1:]

        if isinstance(node, list):
            for item in node:
                _gather(item, remaining_keys)
        elif isinstance(node, dict):
            if key == "*":
                for v in node.values():
                    _gather(v, rest)
            else:
                if key in node:
                    _gather(node[key], rest)
        else:
            # can't traverse further
            return

    _gather(json_obj, keys)

    if not values:
        raise ValueError(f"No numeric values found at path: {path}")

    # Create plot
    fig, ax = plt.subplots(figsize=figsize)
    sns.set_style("whitegrid")

    pt = plot_type.lower()
    if pt == "hist":
        sns.histplot(values, bins=bins, kde=kde, ax=ax, color=color, alpha=alpha)
        if ylabel is None:
            ylabel = "Density" if kde else "Count"
    elif pt == "kde":
        sns.kdeplot(values, ax=ax, fill=True, color=color, alpha=alpha)
        if ylabel is None:
            ylabel = "Density"
    elif pt == "box":
        sns.boxplot(x=values, ax=ax, color=color)
        if ylabel is None:
            ylabel = ""
    elif pt == "violin":
        sns.violinplot(x=values, ax=ax, color=color)
        if ylabel is None:
            ylabel = ""
    elif pt == "ecdf":
        sns.ecdfplot(values, ax=ax, color=color)
        if ylabel is None:
            ylabel = "ECDF"
    else:
        plt.close(fig)
        raise ValueError(f"Unsupported plot_type: {plot_type}. Choose from hist,kde,box,violin,ecdf.")

    # Labels and title defaults
    if xlabel is None:
        # Default xlabel is the provided path string
        xlabel = path if isinstance(path, str) else ".".join(keys)
    if title is None:
        title = f"{pt.upper()} of values at '{xlabel}'"
    ax.set_title(title)
    if xlabel is not None:
        # For box/violin where values plotted on x-axis, label x; otherwise label x axis.
        ax.set_xlabel(xlabel)
    if ylabel is not None:
        ax.set_ylabel(ylabel)

    plt.tight_layout()

    if save_path:
        fig.savefig(save_path, bbox_inches="tight")

    return values, ax
