import numbers
from typing import Any, List, Optional, Tuple, Union
import seaborn as sns
import matplotlib.pyplot as plt
import pandas as pd

def visualize_json_numeric_path(
    json_obj: Any,
    path: Union[str, List[Union[str, int]]],
    kind: str = "hist",
    bins: int = 30,
    agg: Optional[str] = None,
    figsize: Tuple[int, int] = (8, 6),
    kde: bool = True,
    title: Optional[str] = None,
    xlabel: Optional[str] = None,
    ylabel: Optional[str] = None,
    ax: Optional[plt.Axes] = None,
    show: bool = True,
) -> Tuple[plt.Axes, pd.Series]:
    """
    Extract numerical values from a nested JSON-like structure following a specified path of keys
    and visualize them using seaborn.

    Parameters
    - json_obj: The JSON-like object (nested dicts/lists) to extract values from.
    - path: A dot-separated string (e.g. "users.items.value") or a list of keys (strings or ints).
            When traversing a list at any level, the function will recurse into every element.
    - kind: The seaborn plot kind. Supported: "hist", "box", "violin", "strip", "swarm", "line".
    - bins: Number of bins (used for hist).
    - agg: Optional aggregation to apply BEFORE plotting when the final extraction yields a non-flat
           structure per parent. Supported: "mean", "sum", "min", "max", "median", "count".
           If None, the raw flattened numeric values are used.
    - figsize: Figure size (width, height).
    - kde: Whether to draw a KDE on histogram (only for kind="hist").
    - title, xlabel, ylabel: Optional labels for the plot.
    - ax: Optional matplotlib Axes to draw on. If None, a new figure/axes are created.
    - show: If True, plt.show() will be called.

    Returns
    - (ax, series): The matplotlib Axes with the plot and the pandas Series of numeric values plotted.

    Raises
    - ValueError if no numeric values are found or if an unsupported kind/agg is provided.

    Example:
    data = {"users": [{"metrics": {"score": 4}}, {"metrics": {"score": 7}}, {"metrics": {"score": 5}}]}
    visualize_json_numeric_path(data, "users.metrics.score", kind="box")
    """

    # Normalize path to list
    if isinstance(path, str):
        # allow either '.' or '/' or '>' separated paths (common variants)
        if ">" in path:
            keys = [p.strip() for p in path.split(">") if p.strip() != ""]
        elif "/" in path and "." not in path:
            keys = [p.strip() for p in path.split("/") if p.strip() != ""]
        else:
            keys = [p.strip() for p in path.split(".") if p.strip() != ""]
    else:
        keys = list(path)

    # Recursive extractor
    def _extract(obj: Any, remaining_keys: List[Union[str, int]]) -> List[Any]:
        if not remaining_keys:
            # We've reached the "target" object: collect numeric values if possible.
            if obj is None:
                return []
            if isinstance(obj, numbers.Number):
                return [obj]
            if isinstance(obj, (list, tuple)):
                vals = []
                for item in obj:
                    if isinstance(item, numbers.Number):
                        vals.append(item)
                    else:
                        # If elements are nested, attempt to collect numeric children
                        vals.extend(_extract(item, []))
                return vals
            # dict or other non-numeric scalar -> try to find numeric leaves
            if isinstance(obj, dict):
                vals = []
                for v in obj.values():
                    vals.extend(_extract(v, []))
                return vals
            return []
        else:
            key = remaining_keys[0]
            rest = remaining_keys[1:]

            # If current object is a dict, follow the key if present
            if isinstance(obj, dict):
                if key in obj:
                    return _extract(obj[key], rest)
                # If key is int-like, try to use it as index? Not typical for dict keys; skip.
                return []
            # If current object is a list/tuple, recurse into each element with same key
            if isinstance(obj, (list, tuple)):
                vals = []
                for element in obj:
                    vals.extend(_extract(element, remaining_keys))
                return vals
            # If current object is scalar and keys remain -> cannot traverse
            return []

    raw_values = _extract(json_obj, keys)

    # Filter numeric (some recursion might add non-numeric)
    numeric_values = [v for v in raw_values if isinstance(v, numbers.Number)]

    if not numeric_values:
        raise ValueError(f"No numeric values found at path {path!r}.")

    # If aggregation requested, compute per-group aggregation if possible.
    # The extractor produces a flattened list; aggregation here will reduce the whole list.
    supported_aggs = {"mean", "sum", "min", "max", "median", "count"}
    if agg is not None:
        agg = agg.lower()
        if agg not in supported_aggs:
            raise ValueError(f"Unsupported agg '{agg}'. Supported: {supported_aggs}")
        s = pd.Series(numeric_values)
        if agg == "mean":
            series = pd.Series([s.mean()])
        elif agg == "sum":
            series = pd.Series([s.sum()])
        elif agg == "min":
            series = pd.Series([s.min()])
        elif agg == "max":
            series = pd.Series([s.max()])
        elif agg == "median":
            series = pd.Series([s.median()])
        elif agg == "count":
            series = pd.Series([s.count()])
    else:
        series = pd.Series(numeric_values)

    # Prepare plotting axis
    if ax is None:
        plt.figure(figsize=figsize)
        ax = plt.gca()

    # Title and labels defaults
    if title is None:
        title = f"Values at path: {path}" if isinstance(path, str) else f"Values at path: {'.'.join(map(str, keys))}"
    if xlabel is None:
        xlabel = xlabel if xlabel is not None else ""
    if ylabel is None:
        if kind in ("box", "violin", "strip", "swarm"):
            ylabel = ylabel if ylabel is not None else ""
        else:
            ylabel = ylabel if ylabel is not None else "Value"

    # Plot using seaborn
    kind = kind.lower()
    try:
        if kind == "hist":
            sns.histplot(series, bins=bins, kde=kde, ax=ax)
        elif kind == "box":
            sns.boxplot(x=series, ax=ax)
        elif kind == "violin":
            sns.violinplot(x=series, ax=ax)
        elif kind == "strip":
            sns.stripplot(x=series, ax=ax, jitter=True)
        elif kind == "swarm":
            sns.swarmplot(x=series, ax=ax)
        elif kind == "line":
            sns.lineplot(x=series.index, y=series.values, ax=ax)
        else:
            raise ValueError(f"Unsupported plot kind '{kind}'. Supported kinds: hist, box, violin, strip, swarm, line.")
    except Exception:
        # If seaborn fails for certain data shapes fallback to a simple matplotlib plot
        if kind == "hist":
            ax.hist(series.dropna().values, bins=bins)
        elif kind in ("box", "violin", "strip", "swarm"):
            ax.boxplot(series.dropna().values)
        else:
            ax.plot(series.index, series.values)

    ax.set_title(title)
    if xlabel:
        ax.set_xlabel(xlabel)
    else:
        # For horizontal-oriented categorical-like plots, don't force xlabel
        if kind in ("line", "hist"):
            ax.set_xlabel(xlabel if xlabel is not None else "Index")
    if ylabel:
        ax.set_ylabel(ylabel)
    else:
        if kind in ("line", "hist"):
            ax.set_ylabel("Value")

    if show:
        plt.show()

    return ax, series
