def extract_and_plot_from_json(
    json_obj: Any,
    path: Union[str, List[Union[str,int,None]], Tuple[Union[str,int,None], ...]],
    plot_type: str = "hist",
    bins: int = 30,
    kde: bool = False,
    color: Optional[str] = None,
