    title: Optional[str] = None,
    xlabel: Optional[str] = None,
    ylabel: Optional[str] = None,
    seaborn_style: str = "darkgrid",
    return_data: bool = False,
    show: bool = True,
) -> Union[List[float], Tuple[List[float], plt.Figure, plt.Axes]]:
    """
    Extract numeric values from json_obj following 'path' and visualize them using seaborn.

    Parameters
    - json_obj: JSON-like object (nested dicts/lists) to extract from.
    - path: Path to follow. Can be:
        - list/tuple of keys/indices (e.g. ['users', '*', 'score'] or ['users', 0, 'score'])
        - dot-separated string (e.g. "users.*.score")
      Special path elements:
        - '*' or None means "apply to all items" when the current node is a list.
        - integer indices allowed when current node is a list.
    - plot_type: One of 'hist', 'kde', 'box', 'violin', 'strip', 'ecdf'.
    - bins: Number of bins for hist (ignored for other plot types).
    - kde: If True and plot_type == 'hist', overlay a KDE on the histogram.
    - color: Color for the plot (passed to seaborn).
    - figsize: Figure size tuple (width, height).
    - title, xlabel, ylabel: Labels for the plot. If omitted, sensible defaults are used.
    - seaborn_style: seaborn style to use (e.g. 'darkgrid', 'whitegrid').
    - return_data: If True, return (data_list, fig, ax). Otherwise return fig, ax.
    - show: If True, calls plt.show() before returning.

    Returns
    - If return_data is False: (fig, ax)
    - If return_data is True: (data_list, fig, ax)

    Example:
    data = {
        "users": [
            {"id": 1, "score": 9.5},
            {"id": 2, "score": 7.0},
            {"id": 3, "score": 8.2}
        ]
    }
    extract_and_plot_from_json(data, "users.*.score", plot_type="hist", bins=10, title="Scores")
    """

    # Normalize path to list
    if isinstance(path, str):
        # split on dot but keep empty components if any (unlikely)
        path_list = [p if p != "" else None for p in path.split(".")]
    elif isinstance(path, (list, tuple)):
        path_list = list(path)
    else:
        raise TypeError("path must be a string, list, or tuple.")

    def _is_number_like(x):
        if isinstance(x, numbers.Number):
            return True
        # allow numeric strings like "3.14" or "42"
        if isinstance(x, str):
            try:
                float(x)
                return True
            except ValueError:
                return False
        return False

    def _to_number(x):
        if isinstance(x, numbers.Number):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x)
            except ValueError:
                raise ValueError(f"Cannot convert string to float: {x!r}")
        raise ValueError(f"Unsupported numeric type: {type(x)}")

    # Recursively traverse structure following path_list, collecting numeric leaves.
    def traverse(node: Any, remaining_path: List[Union[str,int,None]]) -> List[float]:
        if not remaining_path:
            # At target: collect numeric leaves contained here.
            collected = []
            if node is None:
                return collected
            if isinstance(node, list):
                for item in node:
                    if _is_number_like(item):
                        collected.append(_to_number(item))
                    else:
                        # If nested lists/dicts, attempt to recursively find numbers
                        if isinstance(item, (list, dict)):
                            collected.extend(traverse(item, []))
                return collected
            if isinstance(node, dict):
                # collect numbers from all values in dict
                for v in node.values():
                    if _is_number_like(v):
                        collected.append(_to_number(v))
                    elif isinstance(v, (list, dict)):
                        collected.extend(traverse(v, []))
                return collected
            if _is_number_like(node):
                return [_to_number(node)]
            return collected

        key = remaining_path[0]
        rest = remaining_path[1:]
        results: List[float] = []

        # If current node is a list, we usually either apply key to all elements or index into it.
        if isinstance(node, list):
            # wildcard or None: apply to each element
            if key in ("*", None):
                for item in node:
                    results.extend(traverse(item, rest))
                return results
            # integer index
            if isinstance(key, int):
                try:
                    item = node[key]
                except Exception:
                    return results
                return traverse(item, rest)
            # string that can be converted to int?
            if isinstance(key, str) and key.isdigit():
                idx = int(key)
                try:
                    item = node[idx]
                except Exception:
                    return results
                return traverse(item, rest)
            # non-integer key: attempt to apply to each element if they are dicts
            for item in node:
                if isinstance(item, dict) and key in item:
                    results.extend(traverse(item[key], rest))
            return results

        # If current node is a dict, grab the key (if exists)
        if isinstance(node, dict):
            if key in node:
                return traverse(node[key], rest)
            # For convenience, if key is '*' or None, apply to all values
            if key in ("*", None):
                for v in node.values():
                    results.extend(traverse(v, rest))
                return results
            # key not present: nothing to collect
            return results

        # If node is scalar and still keys remain => cannot descend
        return results

    data_values = traverse(json_obj, path_list)

    if not data_values:
        raise ValueError("No numeric values found at the specified path.")

    # Plotting
    sns.set_style(seaborn_style)
    fig, ax = plt.subplots(figsize=figsize)

    plot_type = plot_type.lower()
    if plot_type == "hist":
        sns.histplot(data_values, bins=bins, kde=kde, ax=ax, color=color)
        if ylabel is None:
            ylabel = "Count"
        if xlabel is None:
            xlabel = xlabel or "Value"
    elif plot_type == "kde":
        sns.kdeplot(data_values, ax=ax, color=color, fill=True)
        if xlabel is None:
            xlabel = "Value"
        if ylabel is None:
            ylabel = "Density"
    elif plot_type == "box":
        sns.boxplot(y=data_values, ax=ax, color=color)
        if xlabel is None:
            xlabel = ""
        if ylabel is None:
            ylabel = "Value"
    elif plot_type == "violin":
        sns.violinplot(y=data_values, ax=ax, color=color)
        if xlabel is None:
            xlabel = ""
        if ylabel is None:
            ylabel = "Value"
    elif plot_type == "strip":
        sns.stripplot(y=data_values, ax=ax, color=color, jitter=True)
        if xlabel is None:
            xlabel = ""
        if ylabel is None:
            ylabel = "Value"
    elif plot_type == "ecdf":
        sns.ecdfplot(data_values, ax=ax, color=color)
        if xlabel is None:
            xlabel = "Value"
        if ylabel is None:
            ylabel = "Proportion"
    else:
        plt.close(fig)
        raise ValueError(f"Unsupported plot_type: {plot_type!r}. Choose from 'hist','kde','box','violin','strip','ecdf'.")

    # Labels and title
    if title:
        ax.set_title(title)
    if xlabel is not None:
        ax.set_xlabel(xlabel)
    if ylabel is not None:
        ax.set_ylabel(ylabel)

    plt.tight_layout()
    if show:
