```python
import json
from typing import Any, List, Union, Optional
import numbers

import numpy as np
import seaborn as sns
import matplotlib.pyplot as plt


def extract_and_plot(
    json_obj: Any,
    key_path: Union[str, List[str]],
    plot_type: str = "hist",
    bins: int = 30,
    figsize: tuple = (8, 4),
    title: Optional[str] = None,
    kde: bool = True,
    convert_numeric_strings: bool = True,
    return_data: bool = False,
):
    """
    Extract numerical values from a nested JSON-like object following a path of keys,
    then visualize those values using seaborn.

    Parameters
    - json_obj: loaded JSON (nested dicts/lists).
    - key_path: list of keys or dot-separated string naming the path to follow.
                Example: ["root", "items", "value"] or "root.items.value".
                If at some level you hit a list, the function will descend into each element.
    - plot_type: one of {"hist", "box", "violin", "line", "bar"}. Default "hist".
                - "hist": histogram (with optional KDE)
                - "box": boxplot
                - "violin": violin plot
                - "line": line plot of values versus index
                - "bar": bar plot of values versus index
    - bins: number of bins for histogram
    - figsize: matplotlib figure size
    - title: optional title for the plot
    - kde: whether to draw KDE on histogram (only for "hist")
    - convert_numeric_strings: try to convert string values that look like numbers
    - return_data: if True, return the extracted numeric list in addition to showing plot

    Returns
    - If return_data is False: None (just shows plot)
    - If return_data is True: list of extracted numeric values

    Raises:
    - ValueError if no numeric data were found along the specified path.
    """

    # Normalize key_path to list
    if isinstance(key_path, str):
        keys = [k for k in key_path.split(".") if k != ""]
    elif isinstance(key_path, list):
        keys = key_path
    else:
        raise TypeError("key_path must be a list of keys or a dot-separated string")

    def try_convert_number(x):
        # Return a Python number or None if not numeric
        if isinstance(x, bool):
            return None
        if isinstance(x, numbers.Number):
            return x
        if convert_numeric_strings and isinstance(x, str):
            try:
                if "." in x or "e" in x.lower():
                    return float(x)
                else:
                    return int(x)
            except Exception:
                try:
                    return float(x)
                except Exception:
                    return None
        return None

    def traverse(node, idx, out_list):
        # Recursively traverse node following keys[idx:]
        if idx >= len(keys):
            # At target: collect numeric values from node. Node may be a number, list, or nested.
            if node is None:
                return
            if isinstance(node, list) or isinstance(node, tuple) or isinstance(node, np.ndarray):
                for elem in node:
                    if isinstance(elem, (list, tuple, dict, np.ndarray)):
                        traverse(elem, idx, out_list)
                    else:
                        n = try_convert_number(elem)
                        if n is not None:
                            out_list.append(n)
            elif isinstance(node, dict):
                # collect numeric values from dict's values
                for v in node.values():
                    if isinstance(v, (list, tuple, dict, np.ndarray)):
                        traverse(v, idx, out_list)
                    else:
                        n = try_convert_number(v)
                        if n is not None:
                            out_list.append(n)
            else:
                n = try_convert_number(node)
                if n is not None:
                    out_list.append(n)
            return

        key = keys[idx]
        if isinstance(node, dict):
            if key in node:
                traverse(node[key], idx + 1, out_list)
            else:
                # key not present: nothing to collect here
                return
        elif isinstance(node, list) or isinstance(node, tuple) or isinstance(node, np.ndarray):
            for item in node:
                traverse(item, idx, out_list)
        else:
            # cannot descend further
            return

    results: List[float] = []
    traverse(json_obj, 0, results)

    if not results:
        raise ValueError(f"No numeric data found at path {keys!r}")

    # Convert to numpy array for plotting convenience
    vals = np.array(results, dtype=float)

    # Prepare plot
    plt.figure(figsize=figsize)
    sns.set(style="whitegrid")

    title_final = title if title is not None else f"Values at {'.'.join(keys)} (n={len(vals)})"

    if plot_type == "hist":
        # seaborn.histplot with KDE
        sns.histplot(vals, bins=bins, kde=kde, stat="count")
        plt.xlabel("Value")
        plt.ylabel("Count")
        plt.title(title_final)
    elif plot_type == "box":
        sns.boxplot(x=vals)
        plt.xlabel("Value")
        plt.title(title_final)
    elif plot_type == "violin":
        sns.violinplot(x=vals)
        plt.xlabel("Value")
        plt.title(title_final)
    elif plot_type == "line":
        sns.lineplot(x=np.arange(len(vals)), y=vals, marker="o")
        plt.xlabel("Index")
        plt.ylabel("Value")
        plt.title(title_final)
    elif plot_type == "bar":
        sns.barplot(x=np.arange(len(vals)), y=vals)
        plt.xlabel("Index")
        plt.ylabel("Value")
        plt.title(title_final)
    else:
        raise ValueError(f"Unsupported plot_type: {plot_type!r}")

    plt.tight_layout()
    plt.show()

    if return_data:
        return results


# Example usage
if __name__ == "__main__":
    sample_json = {
        "root": {
            "items": [
                {"value": 10, "meta": {"score": "1.5"}},
                {"value": 20},
                {"value": "30"},
                {"value": None},
                {"value": [5, 6, "7"]},
                {"other": 100},
            ],
            "summary": {"avg": 12.5}
        },
        "extra": [{"items": [{"value": 3}, {"value": "4.2"}]}]
    }

    # Extract all values under root.items.value and plot histogram
    extract_and_plot(sample_json, "root.items.value", plot_type="hist", bins=8, title="Item Values")

    # Extract values appearing anywhere that follow the path extra.items.value
    data = extract_and_plot(sample_json, "extra.items.value", plot_type="box", return_data=True)
    print("Extracted:", data)
