def process_json_minmax_plot(json_str, output_file=None, feature=None, use_sklearn=True):
    """
    Parse a JSON string to extract numerical data, Min-Max normalize it,
    and generate a line plot.

    Parameters:
    - json_str: str, JSON string containing numeric data. Supported formats:
        * [1, 2, 3, ...]
        * {"series1": [1,2,3], "series2": [...]} (will pick `feature` or first numeric list)
        * [{"x":1,"y":2}, {"x":2,"y":3}, ...] (will pick `feature` key or first numeric key)
        * 123 (single number)
    - output_file: str or None. If provided, save plot to this path. If None, show plot.
    - feature: str. For dicts/lists-of-dicts, pick this key/series name. If None, the function auto-selects the first numeric series.
    - use_sklearn: bool. If True, attempt to use scikit-learn's MinMaxScaler; if unavailable, fallback to pure-Python scaling.

    Returns:
    - normalized: list of floats (values scaled to [0,1])
    """
    import json
    import math
    try:
        import matplotlib.pyplot as plt
    except Exception as e:
        raise RuntimeError("matplotlib is required for plotting. Install it (pip install matplotlib).") from e

    def is_number(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool) and not (isinstance(x, float) and math.isnan(x))

    # Parse JSON
    try:
        data = json.loads(json_str)
    except Exception as e:
        raise ValueError("Invalid JSON input") from e

    # Extract numeric sequence
    seq = None

    # Case: a bare number
    if is_number(data):
        seq = [float(data)]
    # Case: list
    elif isinstance(data, list):
        if len(data) == 0:
            seq = []
        else:
            # List of numbers?
            if all(is_number(x) for x in data):
                seq = [float(x) for x in data]
            # List of dicts?
            elif all(isinstance(x, dict) for x in data):
                # If feature provided, use it
                if feature:
                    try:
                        seq = [float(item[feature]) for item in data if feature in item and is_number(item[feature])]
                    except Exception:
                        raise ValueError(f"Feature '{feature}' not present or not numeric in all items.")
                else:
                    # find first key that is numeric across items
                    first = data[0]
                    found_key = None
                    for k in first.keys():
                        if all((k in item and is_number(item[k])) for item in data):
                            found_key = k
                            break
                    if found_key is None:
                        raise ValueError("No consistent numeric key found in list of objects. Provide 'feature'.")
                    seq = [float(item[found_key]) for item in data]
            # List of lists/tuples?
            elif all(isinstance(x, (list, tuple)) and len(x) > 0 for x in data):
                # If feature is numeric index as string or int, try to use that index
                if feature is not None:
                    try:
                        idx = int(feature)
                        seq = []
                        for item in data:
                            if len(item) > idx and is_number(item[idx]):
                                seq.append(float(item[idx]))
                            else:
                                raise ValueError("Index out of range or non-numeric element encountered.")
                    except Exception:
                        raise ValueError("feature must be an integer index (or None) for list-of-lists input.")
                else:
                    # take first element from each sub-list if numeric
                    if all(is_number(item[0]) for item in data):
                        seq = [float(item[0]) for item in data]
                    else:
                        raise ValueError("Cannot auto-select numeric values from list-of-lists. Provide 'feature' as index.")
            else:
                raise ValueError("Unsupported list contents for numeric extraction. Provide JSON with numeric list, list-of-dicts, or dict-of-lists.")
    # Case: dict
    elif isinstance(data, dict):
        # If feature provided and is a list in the dict, use it
        if feature and feature in data and isinstance(data[feature], list) and all(is_number(x) for x in data[feature]):
            seq = [float(x) for x in data[feature]]
        else:
            # pick first value that's a numeric list
            chosen = None
            for k, v in data.items():
                if isinstance(v, list) and len(v) > 0 and all(is_number(x) for x in v):
                    chosen = k
                    break
            if chosen is None:
                # maybe dict maps to scalars; try keys sorted by numeric values
                if all(is_number(v) for v in data.values()):
                    # order by insertion order; take values
                    seq = [float(v) for v in data.values()]
                else:
                    raise ValueError("No numeric series found in dict. Provide 'feature' key pointing to a numeric list.")
            else:
                seq = [float(x) for x in data[chosen]]
    else:
        raise ValueError("Unsupported JSON top-level type for numeric extraction.")

    if seq is None:
        raise ValueError("No numeric data extracted from JSON.")

    if len(seq) == 0:
        raise ValueError("Extracted numeric sequence is empty.")

    # Normalize: try sklearn MinMaxScaler if requested
    normalized = None
    if use_sklearn:
        try:
            from sklearn.preprocessing import MinMaxScaler
            import numpy as _np
            arr = _np.array(seq, dtype=float).reshape(-1, 1)
            scaler = MinMaxScaler(feature_range=(0.0, 1.0))
            scaled = scaler.fit_transform(arr).reshape(-1)
            normalized = [float(x) for x in scaled]
        except Exception:
            # fallback to pure-python if sklearn/numpy not available or error
            use_sklearn = False

    if not use_sklearn:
        # Pure-Python Min-Max
        minv = min(seq)
        maxv = max(seq)
        if maxv == minv:
            # all same value -- map to zeros
            normalized = [0.0 for _ in seq]
        else:
            rangev = maxv - minv
            normalized = [float((x - minv) / rangev) for x in seq]

    # Plot
    plt.figure(figsize=(8, 4.5))
    plt.plot(range(len(normalized)), normalized, marker='o', linestyle='-', color='tab:blue')
    plt.title('Min-Max Normalized (0..1)')
    plt.xlabel('Index')
    plt.ylabel('Normalized value')
    plt.grid(True)
    plt.tight_layout()
    if output_file:
        plt.savefig(output_file, bbox_inches='tight')
        plt.close()
    else:
        plt.show()

    return normalized
