    Returns:
    - dict mapping series_name -> list of normalized floats (in the provided feature_range).

    Behavior / Supported JSON shapes (common):
    - A list of numbers -> single series.
    - A list of lists of numbers (homogeneous) -> each inner list becomes a separate series.
    - A list of dicts with the same numeric keys across entries -> each such key becomes a series (values taken in list order).
    - A dict of lists of numbers (all same length) -> each key becomes a series.
    - A dict of numeric values -> values become a single series (order by insertion / JSON order).
    - Other shapes -> function will attempt to recursively extract all numbers and plot them as a single series.

    Raises:
    - ValueError if no numeric data can be extracted.
    """
    def is_number(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool) and not math.isinf(x) and not math.isnan(x)

    def all_numbers(lst):
        return all(is_number(x) for x in lst)

    def list_of_lists_numbers(obj):
        if isinstance(obj, list) and obj and all(isinstance(inner, list) for inner in obj):
            return all_numbers(item for inner in obj for item in inner) if obj else False
        return False

    def extract_numbers_recursive(o, out_list):
        if is_number(o):
            out_list.append(o)
        elif isinstance(o, list):
            for item in o:
                extract_numbers_recursive(item, out_list)
        elif isinstance(o, dict):
            for v in o.values():
                extract_numbers_recursive(v, out_list)
        # ignore other types

    data = json.loads(json_str)

    series = OrderedDict()

    # Case 1: top-level list
    if isinstance(data, list):
        if data and all_numbers(data):
            series['series_0'] = [float(x) for x in data]
        elif data and all(isinstance(item, list) and item and all_numbers(item) for item in data):
            # list of lists of numbers -> each inner list is a series
            for i, inner in enumerate(data):
                series[f'series_{i}'] = [float(x) for x in inner]
        elif data and all(isinstance(item, dict) for item in data):
            # list of dicts -> find numeric keys present in all entries
            # collect keys that exist and are numeric across all elements
            common_keys = set(data[0].keys())
            for entry in data[1:]:
                common_keys &= set(entry.keys())
            numeric_keys = []
            for k in common_keys:
                if all(is_number(entry.get(k)) for entry in data):
                    numeric_keys.append(k)
            if numeric_keys:
                for k in numeric_keys:
                    series[k] = [float(entry[k]) for entry in data]
            else:
                # fallback: flatten all numbers in the list of dicts preserving order
                flat = []
                extract_numbers_recursive(data, flat)
                if flat:
                    series['series_0'] = flat
        else:
            # fallback: flatten all numbers
            flat = []
            extract_numbers_recursive(data, flat)
            if flat:
                series['series_0'] = flat

    # Case 2: top-level dict
    elif isinstance(data, dict):
        values = list(data.values())
        if values and all(is_number(v) for v in values):
            # dict of numeric values -> treat values as a single series in JSON order
            series['series_0'] = [float(v) for v in values]
        elif values and all(isinstance(v, list) for v in values):
            # dict of lists: if lists are numeric and same length -> each key is a series
            lengths = [len(v) for v in values]
            if lengths and all(length == lengths[0] for length in lengths):
                # check numeric
                if all(all(is_number(x) for x in v) for v in values):
                    for k, v in data.items():
                        series[str(k)] = [float(x) for x in v]
                else:
                    # fallback flatten
                    flat = []
                    extract_numbers_recursive(data, flat)
                    if flat:
                        series['series_0'] = flat
            else:
                flat = []
                extract_numbers_recursive(data, flat)
                if flat:
                    series['series_0'] = flat
        else:
            # fallback: flatten
            flat = []
            extract_numbers_recursive(data, flat)
            if flat:
                series['series_0'] = flat
    else:
        # other types: try to extract numbers recursively
        flat = []
        extract_numbers_recursive(data, flat)
        if flat:
            series['series_0'] = flat

    if not series:
        raise ValueError("No numeric data could be extracted from the provided JSON.")

    # Normalize each series independently
    normalized = OrderedDict()
    for name, vals in series.items():
        if not vals:
            raise ValueError(f"Series '{name}' is empty.")
        arr = np.array(vals, dtype=float).reshape(-1, 1)
        scaler = MinMaxScaler(feature_range=feature_range)
        scaled = scaler.fit_transform(arr).flatten().tolist()
        normalized[name] = scaled

    # Plot
    plt.figure(figsize=figsize)
    for name, vals in normalized.items():
        x = list(range(len(vals)))
        plt.plot(x, vals, marker='o', label=name)
    plt.xlabel('Index')
    plt.ylabel(f'Normalized (range={feature_range})')
    plt.title('Min-Max Normalized Series')
    if len(normalized) > 1:
        plt.legend()
    plt.grid(True)
    plt.tight_layout()

    if output_path:
        plt.savefig(output_path)
        plt.close()
    else:
        if show:
            plt.show()
        else:
            plt.close()

    # Return normalized data as regular dict
    return {k: list(v) for k, v in normalized.items()}
```

