from typing import Optional, Tuple
from PIL import Image, ExifTags
import pytesseract

def extract_text_from_image(
    image_path: str,
    target_encoding: str = "utf-8",
    ocr_lang: Optional[str] = None,
    return_bytes: bool = True
) -> Tuple[str, Optional[bytes], str]:
    """
    Open an image, extract text with pytesseract OCR, convert the text to `target_encoding`.
    If OCR yields no usable text, attempt to read image comments/metadata (PNG tEXt, JPEG comment,
    EXIF ImageDescription / UserComment, etc.) as a fallback.

    Args:
        image_path: Path to the image file to open.
        target_encoding: The encoding to convert the extracted text to (default 'utf-8').
        ocr_lang: Optional tesseract language code(s) (e.g. 'eng', 'eng+fra'); passed to pytesseract.
        return_bytes: If True, also return the encoded bytes for `target_encoding`. If False,
                      the second returned item will be None.

    Returns:
        (text_str, encoded_bytes_or_None, source)
        - text_str: the extracted (Unicode) text (may contain replacement characters if needed).
        - encoded_bytes_or_None: bytes of text_str encoded using target_encoding if return_bytes True,
                                 otherwise None.
        - source: 'ocr' if text came from OCR, 'comment' if from image comments/metadata, or 'none'
                  if nothing found.
    """

    # Optional helper: use chardet if installed to detect encoding of raw bytes
    try:
        import chardet
    except Exception:
        chardet = None

    def _decode_bytes(bs: bytes) -> str:
        """Try several decodings to get a Python str from bytes."""
        if not isinstance(bs, (bytes, bytearray)):
            # if already a str, just return
            return str(bs)
        # try utf-8 first
        for enc in ("utf-8", "utf-8-sig", "utf-16", "utf-16le", "utf-16be", "cp1252", "latin-1"):
            try:
                return bs.decode(enc)
            except Exception:
                pass
        # try chardet if available
        if chardet is not None:
            try:
                guess = chardet.detect(bs)
                if guess and guess.get("encoding"):
                    return bs.decode(guess["encoding"], errors="replace")
            except Exception:
                pass
        # final fallback: latin-1 (never fails)
        return bs.decode("latin-1", errors="replace")

    def _encode_text(s: str) -> bytes:
        """Encode a str to target_encoding, replacing problematic chars if necessary."""
        try:
            return s.encode(target_encoding)
        except (UnicodeEncodeError, LookupError):
            return s.encode(target_encoding, errors="replace")

    # Open image
    try:
        im = Image.open(image_path)
    except Exception as e:
        raise IOError(f"Unable to open image {image_path!r}: {e}")

    # 1) Try OCR first
    try:
        ocr_kwargs = {}
        if ocr_lang:
            ocr_kwargs["lang"] = ocr_lang
        ocr_text = pytesseract.image_to_string(im, **ocr_kwargs)
    except Exception as e:
        # If tesseract fails, treat as empty OCR result and continue to metadata fallback
        ocr_text = ""
    if isinstance(ocr_text, bytes):
        # In unlikely case pytesseract returned bytes, decode
        ocr_text = _decode_bytes(ocr_text)
    ocr_text = (ocr_text or "").strip()
    if ocr_text:
        encoded = _encode_text(ocr_text) if return_bytes else None
        return ocr_text, encoded, "ocr"

    # 2) Fallback: look for image comments / metadata
    comments = []

    # PIL stores some PNG text and JPEG comments in info dict
    info = getattr(im, "info", {}) or {}
    for k, v in info.items():
        # Many entries in info may be strings or bytes
        if isinstance(v, (bytes, bytearray)):
            comments.append(_decode_bytes(bytes(v)))
        else:
            # make sure to stringify values
            comments.append(str(v))

    # EXIF tags: ImageDescription (0x010E = 270), UserComment (0x9286 = 37510)
    try:
        exif = im.getexif()
        if exif:
            # exif may be a mapping of tag_id: value
            # prefer typical text tags
            for tag_id in (270, 37510):  # ImageDescription, UserComment
                if tag_id in exif:
                    val = exif.get(tag_id)
                    if isinstance(val, (bytes, bytearray)):
                        # EXIF UserComment sometimes stores an encoding prefix; attempt to handle common formats
                        # Some formats: ASCII\0\0\0 + data, UNICODE\0 + UTF-16 data, etc.
                        bval = bytes(val)
                        # Try to strip common prefixes:
                        try:
                            # If starts with ASCII cz prefix
                            if bval[:8].startswith(b"ASCII"):
                                # skip prefix up to first null
                                idx = bval.find(b'\x00')
                                if idx >= 0:
                                    bval = bval[idx+1:]
                            elif bval[:8].startswith(b"UNICODE") or bval[:8].startswith(b"UTF"):
                                # Often UTF-16 BE/LE follows; try to decode directly below
                                pass
                        except Exception:
                            pass
                        comments.append(_decode_bytes(bval))
                    else:
                        comments.append(str(val))
            # Also include any other textual exif fields
            for tag_id, val in exif.items():
                # skip tags already processed
                if tag_id in (270, 37510):
                    continue
                if isinstance(val, (str, bytes, bytearray)) and val:
                    if isinstance(val, (bytes, bytearray)):
                        comments.append(_decode_bytes(bytes(val)))
                    else:
                        comments.append(str(val))
    except Exception:
        # ignore exif read errors
        pass

    # Filter/clean comments
    comments = [c.strip() for c in comments if c and str(c).strip()]
    combined = "\n".join(comments).strip()
    if combined:
        encoded = _encode_text(combined) if return_bytes else None
        return combined, encoded, "comment"

    # Nothing found
    return "", (b"" if return_bytes else None), "none"


# Example usage:
if __name__ == "__main__":
    path = "example.png"
    text, encoded, source = extract_text_from_image(path, target_encoding="utf-8")
    print("Source:", source)
    print("Text (first 400 chars):", text[:400])
    if encoded is not None:
        print("Encoded bytes length:", len(encoded))
```

Notes:
- The function returns Unicode text (text_str) which is the canonical Python string result. If you requested encoded bytes (return_bytes=True), you also get the bytes converted to target_encoding.
- We attempt multiple decodings for raw bytes (utf-8, utf-16 variants, cp1252, latin-1). If chardet is installed, it's used to improve detection.
- You can pass ocr_lang to pytesseract.image_to_string to specify languages (e.g., 'eng', 'eng+fra').
- If pytesseract or Pillow raises an error while opening or OCRing, an informative exception is raised only for inability to open the file; OCR failures fall back to metadata.

