from datetime import datetime
import sys

# Try to get ZoneInfo (stdlib py3.9+ or backports)
try:
    from zoneinfo import ZoneInfo  # Python 3.9+
except Exception:
    try:
        from backports.zoneinfo import ZoneInfo  # backport package
    except Exception:
        ZoneInfo = None

# Try to import dateutil.parser for robust parsing
try:
    from dateutil import parser as _dateutil_parser
except Exception:
    _dateutil_parser = None

# Try to import pytz for disambiguation if installed
try:
    import pytz
except Exception:
    pytz = None


def convert_timezone(time_str, from_tz, to_tz, fmt_out="%Y-%m-%dT%H:%M:%S%z", is_dst=None):
    """
    Convert a time string from one timezone to another, considering DST.

    Parameters:
    - time_str: input time string (if it already contains timezone offset or name, that tz is used
                and `from_tz` is ignored). ISO-8601 strings are supported; dateutil parser accepted
                if python-dateutil is installed.
    - from_tz: source timezone name (IANA tz database name, e.g. "America/New_York"). Used only if
               parsed datetime is naive (no tzinfo).
    - to_tz: destination timezone name (IANA tz database name).
    - fmt_out: strftime format for the output string. Default returns an ISO-like string with numeric offset.
               If fmt_out is None, the function returns a timezone-aware datetime object.
    - is_dst: optional (None/True/False). When using pytz, can be passed to localize() to disambiguate
              ambiguous times (True -> DST, False -> standard). If None, pytz.localize will raise on ambiguity.
              zoneinfo fallback does not accept is_dst; ambiguous handling is best-effort.

    Returns:
    - formatted string (according to fmt_out) or datetime if fmt_out is None.

    Raises:
    - ValueError with helpful message on parse errors, missing tz support, or ambiguous/nonexistent times when
      using pytz with no is_dst provided.
    """
    # Parse the input time string
    dt = None
    parse_err = None
    if _dateutil_parser:
        try:
            # dateutil will parse many formats; keep default behavior
            dt = _dateutil_parser.parse(time_str)
        except Exception as e:
            parse_err = e
    else:
        # Try Python 3.7+'s fromisoformat for common ISO forms
        try:
            dt = datetime.fromisoformat(time_str)
        except Exception as e:
            parse_err = e

    if dt is None:
        raise ValueError(f"Could not parse time string '{time_str}'; dateutil.parser not available or parse failed. "
                         f"Original error: {parse_err}")

    # If parsed datetime already has tzinfo, use it and ignore from_tz
    if dt.tzinfo is not None:
        # If ZoneInfo/pytz requested for conversion we still accept the parsed tz-aware dt
        dest_tz = _get_zone_obj(to_tz)
        if dest_tz is None:
            raise ValueError("No timezone support available. Install Python 3.9+ (zoneinfo) or pytz/backports.zoneinfo.")
        converted = dt.astimezone(dest_tz)
        return _format_or_return(converted, fmt_out)

    # dt is naive; interpret in from_tz
    # Prefer pytz if present and is_dst is provided or if you want strict disambiguation
    if pytz:
        # Use pytz.localize which can detect ambiguous/nonexistent times and accepts is_dst
        tz_from = None
        tz_to = None
        try:
            tz_from = pytz.timezone(from_tz)
        except Exception as e:
            raise ValueError(f"Invalid from_tz '{from_tz}' for pytz: {e}")
        try:
            tz_to = pytz.timezone(to_tz)
        except Exception as e:
            raise ValueError(f"Invalid to_tz '{to_tz}' for pytz: {e}")

        try:
            # If is_dst is None and the time is ambiguous, pytz will raise AmbiguousTimeError; that's useful
            aware = tz_from.localize(dt, is_dst=is_dst)
        except Exception as e:
            # Provide helpful error messages for common pytz exceptions
            name = getattr(e, "__class__", type(e)).__name__
            if name in ("AmbiguousTimeError", "NonExistentTimeError"):
                raise ValueError(f"Time '{time_str}' is {name}. Try supplying is_dst=True or is_dst=False to disambiguate. Original error: {e}")
            else:
                raise ValueError(f"Could not localize naive datetime with pytz: {e}")

        converted = aware.astimezone(tz_to)
        return _format_or_return(converted, fmt_out)

    # No pytz -> use zoneinfo (std lib) if available
    if ZoneInfo is None:
        raise ValueError("No timezone support available: install python-dateutil + pytz, or use Python 3.9+ (zoneinfo), "
                         "or install backports.zoneinfo.")

    try:
        tz_from = ZoneInfo(from_tz)
    except Exception as e:
        raise ValueError(f"Invalid from_tz '{from_tz}' for zoneinfo: {e}")
    try:
        tz_to = ZoneInfo(to_tz)
    except Exception as e:
        raise ValueError(f"Invalid to_tz '{to_tz}' for zoneinfo: {e}")

    # Attach tzinfo — zoneinfo does not provide a localize() method or an easy is_dst flag.
    # We set tzinfo directly and then convert; this is the common approach but ambiguous/nonexistent times
    # are not explicitly signaled by zoneinfo when you simply attach tzinfo.
    naive_with_tz = dt.replace(tzinfo=tz_from)

    # astimezone will normalize to the destination tz (and will account for DST appropriately).
    converted = naive_with_tz.astimezone(tz_to)
    return _format_or_return(converted, fmt_out)


def _get_zone_obj(tzname):
    """Return a tz object suitable for astimezone: ZoneInfo or pytz timezone, preferring ZoneInfo."""
    if ZoneInfo:
        try:
            return ZoneInfo(tzname)
        except Exception:
            pass
    if pytz:
        try:
            return pytz.timezone(tzname)
        except Exception:
            pass
    return None


def _format_or_return(dt_obj, fmt_out):
    if fmt_out is None:
        return dt_obj
    # If format uses %z, ensure it's a numeric offset like +HHMM; that's standard
    return dt_obj.strftime(fmt_out)


# Example usage:
if __name__ == "__main__":
    # Example 1: naive string interpreted in America/New_York (handles DST)
    print(convert_timezone("2021-11-07 01:30:00", "America/New_York", "UTC"))
    # Example 2: if the string contains tz offset, from_tz is ignored
    print(convert_timezone("2021-11-07T01:30:00-04:00", "America/New_York", "Europe/London"))
    # Example 3: with pytz and ambiguous time, disambiguate using is_dst
    # If you have pytz installed:
    # print(convert_timezone("2021-11-07 01:30:00", "America/New_York", "UTC", is_dst=True))   # pick DST instance
    # print(convert_timezone("2021-11-07 01:30:00", "America/New_York", "UTC", is_dst=False))  # pick standard-time instance
