from datetime import datetime, timedelta
import sys

def convert_timezone(time_str,
                     from_tz=None,
                     to_tz="UTC",
                     time_format=None,
                     output_format="%Y-%m-%dT%H:%M:%S%z",
                     ambiguous="earlier",
                     nonexistent="shift_forward"):
    """
    Convert a time string from one timezone to another, accounting for DST transitions.

    Parameters:
    - time_str: str. The input time string. May include timezone offset info; if it does,
                from_tz is optional and will be ignored (but if you supply from_tz and the
                string contains tzinfo they must match or you will get the string's tz used).
    - from_tz: str or None. Timezone name (IANA) of the input time (e.g. "America/New_York").
               Required if time_str has no timezone info.
    - to_tz: str. Target timezone name (IANA). Default "UTC".
    - time_format: str or None. If provided, used with datetime.strptime to parse time_str.
                   If None, the function will try datetime.fromisoformat and a few common formats.
    - output_format: str. Format for the returned string (default RFC-ish: "YYYY-MM-DDTHH:MM:SS±HHMM").
    - ambiguous: how to handle ambiguous times (fall-back repeated hour).
                 Options:
                   - "earlier" (default): pick the earlier occurrence (usually DST True)
                   - "later": pick the later occurrence (usually DST False)
                   - True/False: for compatibility with pytz's is_dst flag (True -> DST)
                   - "raise": raise an error if ambiguous
    - nonexistent: how to handle nonexistent local times (spring-forward gap).
                   Options:
                     - "shift_forward" (default): advance by 1 hour
                     - "shift_backward": move back by 1 hour
                     - "raise": raise an error

    Returns:
    - converted time as a formatted string (output_format). The returned datetime is timezone-aware.

    Notes:
    - The function tries to import a module named "ptz" first (if you truly have one).
      If not present it tries "pytz". If neither is available it falls back to Python's
      zoneinfo (Python 3.9+). Full DST-disambiguation support is available when pytz is present.
      zoneinfo is best-effort (fold can be controlled if the parsed string supplies it;
      nonexistent/ambiguous may not raise in the same way).
    - Raises ValueError on parse failures or if from_tz is required but not given.
    """

    # Basic parsing helpers
    def _try_parse(s, fmt=None):
        if fmt:
            return datetime.strptime(s, fmt)
        # try fromisoformat (handles offset if present)
        try:
            return datetime.fromisoformat(s)
        except Exception:
            pass
        # try some common formats
        tried = [
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d %H:%M",
            "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%dT%H:%M",
            "%Y-%m-%d",
            "%m/%d/%Y %H:%M:%S",
            "%m/%d/%Y %H:%M",
        ]
        for t in tried:
            try:
                return datetime.strptime(s, t)
            except Exception:
                continue
        raise ValueError("Unable to parse time string; provide a time_format.")

    # try to import timezone libs: ptz -> pytz -> zoneinfo
    tz_impl = None
    tz_module = None
    try:
        import ptz as tz_module  # if you really have a library named ptz
        tz_impl = "ptz"
    except Exception:
        try:
            import pytz as tz_module
            from pytz.exceptions import AmbiguousTimeError, NonExistentTimeError
            tz_impl = "pytz"
        except Exception:
            # try stdlib zoneinfo (Python 3.9+)
            try:
                from zoneinfo import ZoneInfo
                tz_impl = "zoneinfo"
            except Exception:
                tz_impl = None

    if tz_impl is None:
        raise RuntimeError("No timezone library found. Install pytz or use Python 3.9+ for zoneinfo.")

    # parse datetime
    dt = _try_parse(time_str, time_format)

    # if dt already has tzinfo (aware), prefer that
    has_tzinfo = (dt.tzinfo is not None and dt.tzinfo.utcoffset(dt) is not None)

    if has_tzinfo:
        aware = dt
    else:
        if not from_tz:
            raise ValueError("Input time is naive; from_tz must be provided (IANA tz name).")
        if tz_impl == "ptz":
            # we don't know the API of user ptz; attempt to use similar to pytz
            try:
                tz = tz_module.timezone(from_tz)
                aware = tz.localize(dt)
            except Exception as e:
                raise RuntimeError("ptz present but localization failed: " + str(e))
        elif tz_impl == "pytz":
            tz = tz_module.timezone(from_tz)
            # first try localize with neutral is_dst to detect errors
            try:
                aware = tz.localize(dt, is_dst=None)
            except AmbiguousTimeError:
                if ambiguous == "raise":
                    raise
                # map ambiguous option to is_dst boolean for pytz
                if ambiguous in (True, False):
                    is_dst_flag = bool(ambiguous)
                elif ambiguous == "earlier":
                    # earlier in fall-back is usually DST True
                    is_dst_flag = True
                elif ambiguous == "later":
                    is_dst_flag = False
                else:
                    raise ValueError("ambiguous must be 'earlier', 'later', True/False, or 'raise'")
                aware = tz.localize(dt, is_dst=is_dst_flag)
            except NonExistentTimeError:
                if nonexistent == "raise":
                    raise
                elif nonexistent == "shift_forward":
                    # add one hour then localize; if still problematic, raise
                    cand = dt + timedelta(hours=1)
                    try:
                        aware = tz.localize(cand, is_dst=None)
                    except Exception:
                        # if still fails, try is_dst True/False choices
                        try:
                            aware = tz.localize(cand, is_dst=True)
                        except Exception:
                            aware = tz.localize(cand, is_dst=False)
                elif nonexistent == "shift_backward":
                    cand = dt - timedelta(hours=1)
                    try:
                        aware = tz.localize(cand, is_dst=None)
                    except Exception:
                        try:
                            aware = tz.localize(cand, is_dst=True)
                        except Exception:
                            aware = tz.localize(cand, is_dst=False)
                else:
                    raise ValueError("nonexistent must be 'shift_forward', 'shift_backward', or 'raise'")
        else:  # zoneinfo fallback
            # ZoneInfo doesn't raise on nonexistent/ambiguous in the same way; we do a best-effort attach.
            try:
                tz = ZoneInfo(from_tz)
            except Exception as e:
                raise ValueError(f"Unknown timezone '{from_tz}' for zoneinfo: {e}")
            # If user asked for ambiguous fallback, try setting fold accordingly (0 or 1).
            # If nonexistent: do shift behavior.
            if isinstance(ambiguous, str) and ambiguous in ("earlier", "later"):
                fold_val = 0 if ambiguous == "earlier" else 1
            elif isinstance(ambiguous, bool):
                fold_val = 0 if not ambiguous else 1
            else:
                fold_val = 0
            # handle nonexistent shift
            local_candidate = dt.replace(tzinfo=tz, fold=fold_val)
            # Quick check: compute offset and then convert to UTC and back to see if round-trip stable.
            try:
                # If the time is nonexistent, this roundtrip may produce different time; we use shift if requested.
                roundtrip = local_candidate.astimezone(ZoneInfo("UTC")).astimezone(tz)
                # Often this will succeed; accept it.
                aware = local_candidate
            except Exception:
                if nonexistent == "raise":
                    raise
                elif nonexistent == "shift_forward":
                    aware = (dt + timedelta(hours=1)).replace(tzinfo=tz)
                elif nonexistent == "shift_backward":
                    aware = (dt - timedelta(hours=1)).replace(tzinfo=tz)
                else:
                    raise ValueError("nonexistent must be 'shift_forward', 'shift_backward', or 'raise'")

    # Now convert to target tz
    if tz_impl == "ptz":
        try:
            tz_to = tz_module.timezone(to_tz)
            converted = aware.astimezone(tz_to)
        except Exception as e:
            raise RuntimeError("ptz present but conversion failed: " + str(e))
    elif tz_impl == "pytz":
        tz_to = tz_module.timezone(to_tz)
        # astimezone + normalize to get correct offset name in pytz
        converted = aware.astimezone(tz_to)
        try:
            converted = tz_to.normalize(converted)
        except Exception:
            # normalize may not be necessary
            pass
    else:  # zoneinfo
        try:
            tz_to = ZoneInfo(to_tz)
        except Exception as e:
            raise ValueError(f"Unknown target timezone '{to_tz}' for zoneinfo: {e}")
        converted = aware.astimezone(tz_to)

    return converted.strftime(output_format)


# Example usages:
if __name__ == "__main__":
    # naive input with from_tz
    print(convert_timezone("2021-11-07 01:30:00", from_tz="America/New_York", to_tz="UTC",
                          ambiguous="earlier"))
    print(convert_timezone("2021-11-07 01:30:00", from_tz="America/New_York", to_tz="UTC",
                          ambiguous="later"))

    # ISO with offset (tz included in string) - from_tz ignored
    print(convert_timezone("2021-03-14T02:30:00-05:00", to_tz="America/Los_Angeles"))

    # Provide explicit format
    print(convert_timezone("03/14/2021 02:30", from_tz="America/New_York", to_tz="UTC",
                          time_format="%m/%d/%Y %H:%M"))
