    # Parse input time
    dt = _parse_time(time_str, time_format)

    # If dt is timezone-aware and a from_tz is provided, we will ignore from_tz and convert from dt.tzinfo.
    if dt.tzinfo is not None:
        # Convert directly to target zone
        if _USE_PYTZ:
            try:
                target = pytz.timezone(to_tz)
            except Exception as e:
                raise ValueError(f"Invalid target timezone '{to_tz}': {e}")
            # If dt.tzinfo is not a pytz tzinfo, astimezone will still work
            try:
                converted = dt.astimezone(target)
            except Exception as e:
                raise ValueError(f"Error converting aware datetime: {e}")
        else:
            try:
                target = ZoneInfo(to_tz)
            except Exception as e:
                raise ValueError(f"Invalid target timezone '{to_tz}': {e}")
            try:
                converted = dt.astimezone(target)
            except Exception as e:
                raise ValueError(f"Error converting aware datetime: {e}")
    else:
        # Naive datetime: attach from_tz then convert
        if _USE_PYTZ:
            try:
                src = pytz.timezone(from_tz)
            except Exception as e:
                raise ValueError(f"Invalid source timezone '{from_tz}': {e}")
            try:
                # is_dst can be True/False/None. If None and ambiguous, pytz raises AmbiguousTimeError.
                aware_src = src.localize(dt, is_dst=is_dst)
            except AmbiguousTimeError as e:
                raise ValueError(
                    f"Ambiguous time for timezone {from_tz} at {dt}. "
                    "Provide is_dst=True or is_dst=False to disambiguate."
                )
            except NonExistentTimeError as e:
                raise ValueError(
                    f"Non-existent time for timezone {from_tz} at {dt} (clocks moved forward). "
                    "Provide a different time or handle DST transition."
                )
            try:
                target = pytz.timezone(to_tz)
            except Exception as e:
                raise ValueError(f"Invalid target timezone '{to_tz}': {e}")
            converted = aware_src.astimezone(target)
        else:
            # zoneinfo path
            try:
                src = ZoneInfo(from_tz)
            except Exception as e:
                raise ValueError(f"Invalid source timezone '{from_tz}': {e}")

            # Resolve fold based on is_dst (best-effort):
            # When clocks are set back (ambiguous), first occurrence is typically DST=True.
            # For zoneinfo: fold=0 -> first occurrence, fold=1 -> second occurrence.
            if is_dst is None:
                fold_val = 0
            else:
                # is_dst True -> choose first (DST), fold=0
                # is_dst False -> choose second (standard), fold=1
                fold_val = 0 if is_dst else 1

            aware_src = dt.replace(tzinfo=src, fold=fold_val)

            # Note: zoneinfo does not raise a clear NonExistentTimeError on naive attach; behavior depends.
            # We attempt conversion and let any exceptions surface.
            try:
                target = ZoneInfo(to_tz)
            except Exception as e:
                raise ValueError(f"Invalid target timezone '{to_tz}': {e}")
            try:
                converted = aware_src.astimezone(target)
            except Exception as e:
                raise ValueError(f"Error converting datetime with zoneinfo: {e}")

    # Format output
    if output_format:
        return converted.strftime(output_format)
    # Use ISO 8601 with offset; for pytz, isoformat() may include tzname; that's acceptable
    return converted.isoformat()
