    # convert to target timezone
    converted = [to_target(dt) for dt in parsed]

    # sort (after conversion) to ensure consecutive pairs are chronological
    converted.sort()

    # compute diffs in seconds
    diffs = []
    for a, b in zip(converted, converted[1:]):
        diff = (b - a).total_seconds()
        diffs.append(diff)

    if not diffs:
        raise ValueError("No consecutive differences computed (need at least two timestamps).")

    avg = sum(diffs) / len(diffs)
    return float(avg)

