Here is a single self-contained Python function that uses bs4 to fetch a webpage, finds its <script> tags, and tries to interpret JSON-/object-like strings inside those tags as Python dictionaries. It uses a best-effort heuristic (balanced-brace extraction, comment removal, quoting unquoted keys, converting single to double quotes, removing trailing commas) and tries json.loads first, falling back to ast.literal_eval where helpful.

Note: parsing JavaScript object literals is inherently heuristic (JS allows unquoted keys, functions, comments, trailing commas, etc.). This function makes reasonable attempts but may not succeed for every JS snippet. It also avoids executing any JS code (no eval of arbitrary code).

Copy-paste and call extract_dicts_from_scripts(url).

```python
import re
import json
import ast
import requests
from bs4 import BeautifulSoup

def extract_dicts_from_scripts(url, timeout=10, max_substring_length=1000000):
    """
    Fetch the page at `url`, examine all <script> tags, and attempt to extract
    Python dict objects from strings found in those tags.

    Returns a list of dicts successfully parsed.

    Heuristics used:
    - For scripts with type "application/ld+json" or "application/json", parse whole text with json.loads.
    - Otherwise, find balanced {...} and [...] substrings, strip comments, remove trailing commas,
      quote unquoted keys, convert single-quoted strings to double-quoted, then try json.loads.
    - If json.loads fails, convert JS null/true/false to Python None/True/False and try ast.literal_eval.

    Limitations:
    - This is best-effort only and won't handle arbitrary JS (functions, complex expressions).
    - Do not rely on this for executing remote code (it never executes JS, only parses text).
    """
    def find_brace_substrings(text):
        """Yield substrings that are balanced {...} or [...] starting at each { or [."""
        starts = {'{': '}', '[': ']'}
        n = len(text)
        i = 0
        while i < n:
            if text[i] in starts:
                stack = [starts[text[i]]]
                j = i + 1
                while j < n and stack:
                    ch = text[j]
                    if ch in starts:
                        stack.append(starts[ch])
                    elif stack and ch == stack[-1]:
                        stack.pop()
                    j += 1
                if not stack:
                    yield text[i:j]
                    i = j
                    continue
            i += 1

    def strip_js_comments(s):
        # remove // ... and /* ... */ comments
        return re.sub(r'//.*?$|/\*.*?\*/', '', s, flags=re.MULTILINE | re.DOTALL)

    def remove_trailing_commas(s):
        # remove trailing commas before } or ]
        return re.sub(r',\s*(?=[}\]])', '', s)

    def quote_unquoted_keys_for_json(s):
        # add quotes around unquoted object keys: { key: or , key:
        # This is a heuristic and may misfire in some corner cases.
        return re.sub(r'([{,]\s*)([A-Za-z_][A-Za-z0-9_]*)(\s*):', r'\1"\2"\3:', s)

    def convert_single_to_double_quotes(s):
        # Replace single-quoted strings with double-quoted ones, preserving escapes.
        # Heuristic; may not handle every escape combination perfectly.
        return re.sub(r"(?<!\\)'((?:\\.|[^'\\])*)'", r'"\1"', s)

    def js_to_json_attempt(s):
        """Try to convert a JS-like literal to JSON and json.loads it."""
        s2 = strip_js_comments(s)
        s2 = remove_trailing_commas(s2)
        s2 = quote_unquoted_keys_for_json(s2)
        s2 = convert_single_to_double_quotes(s2)
        # After these transforms try json.loads
        return json.loads(s2)

    def try_parse_substring(s):
        s = s.strip()
        if not s:
            raise ValueError("empty")
        # limit huge substrings
        if len(s) > max_substring_length:
            raise ValueError("substring too large")
        # First try direct json.loads (good for strict JSON)
        try:
            return json.loads(s)
        except Exception:
            pass
        # Try cleaning up JS-ish object into JSON
        try:
            return js_to_json_attempt(s)
        except Exception:
            pass
        # As a last resort try converting to Python literals and ast.literal_eval
        try:
            s_py = strip_js_comments(s)
            s_py = remove_trailing_commas(s_py)
            s_py = re.sub(r'\bnull\b', 'None', s_py)
            s_py = re.sub(r'\btrue\b', 'True', s_py)
            s_py = re.sub(r'\bfalse\b', 'False', s_py)
            # Quote bare keys for Python dicts
            s_py = quote_unquoted_keys_for_json(s_py)
            # Convert single-quoted to double if necessary (literal_eval accepts both)
            # No need to change quotes for literal_eval, but keep consistent
            s_py = convert_single_to_double_quotes(s_py)
            return ast.literal_eval(s_py)
        except Exception as e:
            raise e

    results = []
    try:
        resp = requests.get(url, timeout=timeout, headers={'User-Agent': 'python-requests/bs4-extractor'})
        resp.raise_for_status()
    except Exception as e:
        raise RuntimeError(f"Failed to fetch URL {url!r}: {e}")

    soup = BeautifulSoup(resp.text, 'html.parser')
    scripts = soup.find_all('script')

    for idx, script in enumerate(scripts):
        # Get the inner text of the script
        text = script.string
        if text is None:
            # fall back to get_text which concatenates contents
            text = script.get_text(separator='', strip=False)
        if not text or not text.strip():
            continue

        # If the script type indicates JSON, try parsing the whole text first
        script_type = (script.get('type') or '').lower()
        if script_type in ('application/ld+json', 'application/json'):
            try:
                obj = json.loads(text)
                if isinstance(obj, dict):
                    results.append(obj)
                elif isinstance(obj, list):
                    # optionally collect dict entries from the list
                    for item in obj:
                        if isinstance(item, dict):
                            results.append(item)
                continue
            except Exception:
                # fall through to more aggressive attempts
                pass

        # Look for balanced {...} and [...] substrings and attempt to parse each
        for substr in find_brace_substrings(text):
            try:
                parsed = try_parse_substring(substr)
            except Exception:
                continue
            if isinstance(parsed, dict):
                results.append(parsed)
            elif isinstance(parsed, list):
                # collect dicts inside lists
                for item in parsed:
                    if isinstance(item, dict):
                        results.append(item)
    return results
```

