import re
import urllib.parse
import requests
from bs4 import BeautifulSoup

def extract_title_from_text(text):
    """
    Extracts the first URL found in `text`, fetches that URL, and returns the page <title>.
    If no URL is found or fetching/parsing fails, returns an error message string
    that starts with 'ERROR:' describing the problem.

    Example:
    >>> extract_title_from_text("Check this out: https://example.com/page")
    'Example Domain'
    """
    # 1) Find a URL-like substring: prefer http(s) or www, fall back to bare domains
    m = re.search(r'(?i)\b((?:https?://|www\.)\S+)', text)
    if m:
        url = m.group(1).rstrip('.,;:)]}\'"')  # strip common trailing punctuation
    else:
        m2 = re.search(r'\b([A-Za-z0-9.-]+\.[A-Za-z]{2,})(/[^\s]*)?\b', text)
        if m2:
            url = m2.group(0).rstrip('.,;:)]}\'"')
        else:
            return "ERROR: No valid URL found in input."

    # 2) Ensure URL has a scheme
    parsed = urllib.parse.urlparse(url)
    if not parsed.scheme:
        url = 'http://' + url
        parsed = urllib.parse.urlparse(url)
    if not parsed.netloc:
        return "ERROR: Extracted URL is invalid."

    # 3) Fetch the URL
    try:
        resp = requests.get(url, timeout=10, headers={
            'User-Agent': 'Mozilla/5.0 (compatible; TitleFetcher/1.0)'
        })
    except requests.RequestException as e:
        return f"ERROR: Could not fetch URL: {e}"

    if resp.status_code != 200:
        return f"ERROR: URL returned status code {resp.status_code}."

    # 4) Check content-type (rough check)
    content_type = resp.headers.get('Content-Type', '')
    if 'text/html' not in content_type.lower():
        # still attempt parsing if it's HTML-like, otherwise error
        # (some servers omit content-type, so allow parsing attempt unless clearly non-HTML)
        if 'xml' not in content_type.lower():
            return "ERROR: URL does not appear to be an HTML page."

    # 5) Parse and extract <title> (fall back to og:title / twitter:title)
    try:
        soup = BeautifulSoup(resp.content, 'html.parser')
    except Exception as e:
        return f"ERROR: Failed to parse HTML: {e}"

    title_tag = soup.find('title')
    if title_tag and title_tag.string and title_tag.string.strip():
        return title_tag.string.strip()

    # try common meta fallbacks
    meta_og = soup.find('meta', property='og:title')
    if meta_og and meta_og.get('content'):
        return meta_og['content'].strip()
    meta_tw = soup.find('meta', attrs={'name': 'twitter:title'})
    if meta_tw and meta_tw.get('content'):
        return meta_tw['content'].strip()

    return "ERROR: Title not found on the page."
