import re
from typing import Dict
import requests
from bs4 import BeautifulSoup

def get_title_from_text(text: str, timeout: float = 10.0) -> Dict:
    """
    Extract the first URL from `text`, fetch the page, and return its <title>.
    Returns a dict:
      - On success: {"ok": True, "title": "<page title>"}
      - On error:   {"ok": False, "error": "<descriptive message>"}
    Args:
      text: input string that may contain a URL
      timeout: network timeout in seconds for the HTTP request
    """
    if not isinstance(text, str) or not text.strip():
        return {"ok": False, "error": "No input text provided."}

    # Regex to find common URL forms (http(s)://... or www....)
    url_re = re.compile(r'(https?://[^\s<>"]+|www\.[^\s<>"]+)', re.IGNORECASE)
    m = url_re.search(text)
    if not m:
        return {"ok": False, "error": "No valid URL found in input text."}

    url = m.group(0)
    # If URL starts with 'www.' add scheme
    if url.lower().startswith('www.'):
        url = 'http://' + url

    headers = {
        "User-Agent": "Mozilla/5.0 (compatible; TitleFetcher/1.0; +https://example/)"
    }

    try:
        resp = requests.get(url, headers=headers, timeout=timeout, allow_redirects=True)
    except requests.exceptions.RequestException as e:
        return {"ok": False, "error": f"Failed to fetch URL: {e}"}

    # Check HTTP success
    if resp.status_code < 200 or resp.status_code >= 400:
        return {"ok": False, "error": f"URL returned HTTP status {resp.status_code}."}

    # Check content type if available
    ctype = resp.headers.get("Content-Type", "")
    if "html" not in ctype.lower():
        # still attempt parse, but warn
        return {"ok": False, "error": f"URL did not return an HTML document (Content-Type: {ctype})."}

    # Try to parse HTML and extract title
    try:
        soup = BeautifulSoup(resp.text, "html.parser")
    except Exception as e:
        return {"ok": False, "error": f"Failed to parse HTML: {e}"}

    # Common places for title: <title>, og:title, twitter:title, first H1 as fallback
    title_tag = soup.title.string.strip() if soup.title and soup.title.string else None
    if title_tag:
        return {"ok": True, "title": title_tag}

    # Open Graph
    og = soup.find("meta", property="og:title") or soup.find("meta", attrs={"name": "og:title"})
    if og and og.get("content"):
        return {"ok": True, "title": og["content"].strip()}

    # Twitter title
    tw = soup.find("meta", attrs={"name": "twitter:title"})
    if tw and tw.get("content"):
        return {"ok": True, "title": tw["content"].strip()}

    # First H1
    h1 = soup.find("h1")
    if h1 and h1.get_text(strip=True):
        return {"ok": True, "title": h1.get_text(strip=True)}

    return {"ok": False, "error": "No title found in the fetched HTML."}

